// Security & CORS Middleware
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ limit: '50mb', extended: true }));

// Serve local uploaded files via a protected route instead of public static folder
app.get('/uploads/:filename', (req, res) => {
  const filePath = path.join(process.cwd(), 'uploads', req.params.filename);
  if (fs.existsSync(filePath)) {
    // In a full production app with sessions, you'd verify the user here.
    // For now, these are protected by unguessable long filenames.
    res.sendFile(filePath);
  } else {
    res.status(404).send('File not found');
  }
});

