// Helper to get Google OAuth redirect URI (handles AI Studio iframe / cloud run reverse proxy)
function getGoogleRedirectUri(req: express.Request): string {
  if (process.env.APP_URL) {
    const cleanUrl = process.env.APP_URL.replace(/\/$/, '');
    return `${cleanUrl}/api/auth/google/callback`;
  }
  const protocol = req.headers['x-forwarded-proto'] || req.protocol;
  const host = req.headers['x-forwarded-host'] || req.get('host');
  return `${protocol}://${host}/api/auth/google/callback`;
}

// Shared authentication helper for both email/phone login and Google OAuth
async function authenticateOrRegisterUser(
  email: string,
  phone: string,
  name: string,
  chosenRole?: string,
  password?: string,
  dashboardNumber?: string,
  isRegistration?: boolean
) {
  const normalizedEmail = email ? email.toLowerCase().trim() : '';
  const normalizedPhone = phone ? phone.trim() : '';
  const targetRole = chosenRole || 'customer';
  const cleanPhone = normalizedPhone.replace(/[^0-9]/g, '');

  const userEmail = (normalizedEmail && !normalizedEmail.includes('@nordbase.pt'))
    ? normalizedEmail
    : `${cleanPhone || Date.now()}_${targetRole}@nordbase.pt`;

  if (pool) {
    let client: any = null;
    try {
      client = await pool.connect();
      // Find all accounts matching phone or email
      const findRes = await client.query(
        `SELECT * FROM app_users 
         WHERE (phone = $1 AND phone <> '') 
            OR (email = $2 AND email <> '') 
            OR (email = $3 AND email <> '')`,
        [normalizedPhone, normalizedEmail, userEmail]
      );

      const existingRoleUser = findRes.rows.find((r: any) => r.role === targetRole);
      const existingOtherUser = findRes.rows.find((r: any) => r.role !== targetRole);

      if (existingRoleUser) {
        if (existingRoleUser.is_blocked) {
          return { error: 'Access denied. Your account is blocked. Please contact support.' };
        }
        if ((targetRole === 'operator' || targetRole === 'regional_admin') && existingRoleUser.dashboard_number && existingRoleUser.dashboard_number !== dashboardNumber) {
          return { error: 'Invalid Dashboard Number.' };
        }

        // Verify password if provided
        if (existingRoleUser.password && password && existingRoleUser.password !== password) {
          return { error: 'Incorrect password. Please check your credentials and try again.' };
        }

        // Set password if legacy account without password
        if (!existingRoleUser.password && password) {
          existingRoleUser.password = password;
          await client.query('UPDATE app_users SET password = $1 WHERE id = $2', [password, existingRoleUser.id]);
        }

        if ((!existingRoleUser.name || existingRoleUser.name === 'User') && name) {
          existingRoleUser.name = name;
          await client.query('UPDATE app_users SET name = $1 WHERE id = $2', [name, existingRoleUser.id]);
        }

        return {
          id: existingRoleUser.id,
          email: existingRoleUser.email,
          phone: existingRoleUser.phone || undefined,
          name: existingRoleUser.name,
          role: existingRoleUser.role,
          specialistStatus: existingRoleUser.specialist_status,
          isNewUser: false,
          photoUrl: existingRoleUser.photo_url || undefined,
          verificationDocuments: typeof existingRoleUser.verification_documents === 'string' ? JSON.parse(existingRoleUser.verification_documents) : existingRoleUser.verification_documents || [],
          categories: existingRoleUser.categories || [],
          languages: typeof existingRoleUser.languages === 'string' ? JSON.parse(existingRoleUser.languages) : existingRoleUser.languages || [],
          tradeSkillLevel: existingRoleUser.trade_skill_level || undefined,
          skillsDescription: existingRoleUser.skills_description || undefined,
          specialtiesWithLevels: typeof existingRoleUser.specialties_with_levels === 'string' ? JSON.parse(existingRoleUser.specialties_with_levels) : existingRoleUser.specialties_with_levels || [],
        };
      } else {
        // Role user does not exist yet. Check password against existingOtherUser if present
        if (existingOtherUser && existingOtherUser.password && password && existingOtherUser.password !== password) {
          return { error: 'Incorrect password. Please check your credentials and try again.' };
        }

        const specialistStatus = targetRole === 'specialist' ? 'new' : 'not_requested';
        const userId = `user-${targetRole}-${Date.now()}`;

        const newUser = {
          id: userId,
          email: userEmail,
          phone: normalizedPhone || (existingOtherUser ? existingOtherUser.phone : ''),
          name: name || (existingOtherUser ? existingOtherUser.name : (normalizedEmail && normalizedEmail.includes('@') ? normalizedEmail.split('@')[0] : 'User')),
          role: targetRole,
          specialistStatus,
          password: password || (existingOtherUser ? existingOtherUser.password : null),
        };

        await client.query(
          `INSERT INTO app_users (id, email, phone, name, role, specialist_status, password) 
           VALUES ($1, $2, $3, $4, $5, $6, $7)`,
          [newUser.id, newUser.email, newUser.phone, newUser.name, newUser.role, newUser.specialistStatus, newUser.password]
        );

        return {
          id: newUser.id,
          email: newUser.email,
          phone: newUser.phone || undefined,
          name: newUser.name,
          role: newUser.role,
          specialistStatus: newUser.specialistStatus,
          isNewUser: true,
          photoUrl: undefined,
          verificationDocuments: [],
          categories: [],
          languages: [],
        };
      }
    } catch (err) {
      console.error('Error during Neon DB auth (falling back to in-memory):', err);
    } finally {
      if (client) {
        try { client.release(); } catch (e) { /* ignore release error */ }
      }
    }
  }

  // Fallback Store Authentication (In-Memory)
  const existingRoleUser = inMemoryUsers.find(
    (u) => u.role === targetRole && (
      (normalizedPhone && u.phone === normalizedPhone) ||
      (normalizedEmail && u.email === normalizedEmail)
    )
  );
  const existingOtherUser = inMemoryUsers.find(
    (u) => u.role !== targetRole && (
      (normalizedPhone && u.phone === normalizedPhone) ||
      (normalizedEmail && u.email === normalizedEmail)
    )
  );

  if (existingRoleUser) {
    if (existingRoleUser.isBlocked) {
      return { error: 'Access denied. Your account is blocked. Please contact support.' };
    }
    if ((targetRole === 'operator' || targetRole === 'regional_admin') && existingRoleUser.dashboardNumber && existingRoleUser.dashboardNumber !== dashboardNumber) {
      return { error: 'Invalid Dashboard Number.' };
    }

    if (existingRoleUser.password && password && existingRoleUser.password !== password) {
      return { error: 'Incorrect password. Please check your credentials and try again.' };
    }
    if (!existingRoleUser.password && password) {
      existingRoleUser.password = password;
    }
    return {
      ...existingRoleUser,
      isNewUser: false
    };
  } else {
    if (existingOtherUser && existingOtherUser.password && password && existingOtherUser.password !== password) {
      return { error: 'Incorrect password. Please check your credentials and try again.' };
    }

    const newUser = {
      id: `user-${targetRole}-${Date.now()}`,
      email: userEmail,
      phone: normalizedPhone || (existingOtherUser ? existingOtherUser.phone : ''),
      name: name || (existingOtherUser ? existingOtherUser.name : (normalizedEmail && normalizedEmail.includes('@') ? normalizedEmail.split('@')[0] : 'User')),
      role: targetRole,
      password: password || (existingOtherUser ? existingOtherUser.password : undefined),
      specialistStatus: targetRole === 'specialist' ? 'approved' : 'not_requested',
    };
    inMemoryUsers.push(newUser);
    return {
      ...newUser,
      isNewUser: true
    };
  }
}

