      if (client) client.release();
    }
  }

  // Fallback in-memory onboard (always executes or supplements DB)
  const u = inMemoryUsers.find(usr => usr.id === userId) as any;
  if (u) {
    u.role = role;
    u.name = name;
    u.phone = phone;
    if (role === 'specialist') {
