      if (!exists) {
        inMemorySpecialists.push({
          id: userId,
          name,
          phone,
          category,
          city,
          balance: 100,
          unlockedJobs: [],
          status: u.specialistStatus,
          categories,
          languages,
          tradeSkillLevel,
          skillsDescription,
          photoUrl,
          verificationDocuments,
          specialtiesWithLevels
        } as any);
