} from 'lucide-react';

export default function App() {
  const { t, i18n } = useTranslation();
  const [state, setState] = useState<AppState>(store.getState());
  const [isOffline, setIsOffline] = useState(!navigator.onLine);

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Listen to the store state changes
  useEffect(() => {
    const unsubscribe = store.subscribe((newState) => {
      setState({ ...newState });
    });
    return unsubscribe;
  }, []);

  // Handler Actions
  const handleRoleChange = (role: any) => {
    store.setRole(role);
  };

  const handleSelectCity = (city: string | null) => {
    store.setSelectedCity(city);
  };

  const handleSelectCategory = (category: ServiceCategory | null) => {
    store.setSelectedCategory(category);
  };

  const handleSubmitRequest = (
    name: string,
    phone: string,
    location: string,
    description: string
  ) => {
    return store.createJobRequest(name, phone, location, description);
  };

  const handleSubmitRequestCustomer = (
    name: string,
    phone: string,
    location: string,
    description: string,
    attachments: string[] = [],
    operatorId: string | null = null
  ) => {
    return store.createJobRequest(name, phone, location, description, attachments, operatorId);
  };

  const handleClaimJob = (jobId: string, operatorId: string) => {
    store.claimJob(jobId, operatorId);
  };

  const handleOfferJob = (
    jobId: string,
    hours: number,
    value: number,
    leadPrice: number,
    notes: string,
    specialistIds: string[]
  ) => {
    store.offerJobToSpecialists(jobId, hours, value, leadPrice, notes, specialistIds);
  };

  const handleSelectSpecialistForJob = (jobId: string, specialistId: string) => {
    store.selectSpecialistForJob(jobId, specialistId);
  };

  const handleExpressInterest = (jobId: string, specialistId: string) => {
    return store.expressInterest(jobId, specialistId);
  };

  const handleUnlockJob = (jobId: string, specialistId: string) => {
    return store.unlockJob(jobId, specialistId);
  };

  const handleCompleteJob = (jobId: string) => {
    store.completeJob(jobId);
  };

  const handleAddMessageCustomer = (
    jobId: string,
    sender: 'customer',
    senderName: string,
    content: string,
    channel?: 'customer_operator' | 'customer_specialist',
    attachmentUrl?: string,
    attachmentName?: string
  ) => {
    store.addMessage(jobId, sender, senderName, content, channel, attachmentUrl, attachmentName);
  };

  const handleAddMessageSpecialist = (
    jobId: string,
    sender: 'specialist',
    senderName: string,
    content: string,
    channel?: 'operator_specialist' | 'customer_specialist',
    attachmentUrl?: string,
    attachmentName?: string
  ) => {
    store.addMessage(jobId, sender, senderName, content, channel, attachmentUrl, attachmentName);
  };

  const handleAddMessageOperator = (
    jobId: string,
    sender: 'operator',
    senderName: string,
    content: string,
    channel?: 'customer_operator' | 'operator_specialist' | 'operator_operator' | 'customer_specialist',
    attachmentUrl?: string,
    attachmentName?: string
  ) => {
    store.addMessage(jobId, sender, senderName, content, channel, attachmentUrl, attachmentName);
  };

  const handleTopupSpecialist = (specialistId: string, amount: number) => {
    store.topupSpecialist(specialistId, amount);
  };

  const handleCreateSpecialistProfile = (
    name: string,
    phone: string,
    category: ServiceCategory,
    city: string,
    categories?: ServiceCategory[],
    languages?: { language: string; level: 'basic' | 'conversational' | 'native' }[],
    tradeSkillLevel?: 'amateur' | 'pro' | 'expert',
    skillsDescription?: string,
    photoUrl?: string,
    verificationDocuments?: { type: 'passport' | 'id_card' | 'drivers_license'; name: string; url: string }[]
  ) => {
    store.createSpecialistProfile(name, phone, category, city, categories, languages, tradeSkillLevel, skillsDescription, photoUrl, verificationDocuments);
  };

  const handleSelectSpecialistProfile = (id: string) => {
    store.getState().activeSpecialistId = id;
    setState({ ...store.getState() });
  };

  const [showDevPanel, setShowDevPanel] = useState(false);
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [customerView, setCustomerView] = useState<'menu' | 'dashboard'>('menu');
  const [expectedLoginRole, setExpectedLoginRole] = useState<UserRole>('customer');
  const [isPartnerPage, setIsPartnerPage] = useState(false);
  const [isKnowledgeBase, setIsKnowledgeBase] = useState(false);
  const [isPitchDeck, setIsPitchDeck] = useState(false);
  const [pitchDeckLevel, setPitchDeckLevel] = useState<'tp' | 'rp' | 'investor'>('investor');
  const [kbArticleSlug, setKbArticleSlug] = useState<string | null>(null);
  const navigate = useNavigate();
  const location = useLocation();

  // Unified URL to State sync (mount & navigation changes)
  useEffect(() => {
    const path = location.pathname.toLowerCase();
    const hash = location.hash.toLowerCase();
    const search = location.search.toLowerCase();

    const isPartnerRoute =
      path.startsWith('/partner') ||
      path === '/become-a-partner' ||
      hash === '#/partner' ||
      hash === '#partner' ||
      search.includes('page=partner');

    const isKbRoute = path.startsWith('/knowledge-base');
    const isPitchDeckRoute = path.startsWith('/pitch/');

    if (isPitchDeckRoute) {
      if (!isPitchDeck) setIsPitchDeck(true);
      if (isPartnerPage) setIsPartnerPage(false);
      if (isKnowledgeBase) setIsKnowledgeBase(false);

      if (path === '/pitch/tp-secret') {
        if (pitchDeckLevel !== 'tp') setPitchDeckLevel('tp');
      } else if (path === '/pitch/rp-secret') {
        if (pitchDeckLevel !== 'rp') setPitchDeckLevel('rp');
      } else {
        if (pitchDeckLevel !== 'investor') setPitchDeckLevel('investor');
      }
      return;
    }

    if (isPartnerRoute) {
      if (!isPartnerPage) setIsPartnerPage(true);
      if (isKnowledgeBase) setIsKnowledgeBase(false);
      if (isPitchDeck) setIsPitchDeck(false);
      return;
    }

    if (isKbRoute) {
      if (!isKnowledgeBase) setIsKnowledgeBase(true);
      if (isPartnerPage) setIsPartnerPage(false);
      if (isPitchDeck) setIsPitchDeck(false);
      const parts = location.pathname.split('/knowledge-base');
      const rawSlug = parts[1] ? parts[1].replace(/^\//, '') : null;
      const slug = rawSlug || null;
      if (kbArticleSlug !== slug) setKbArticleSlug(slug);
      return;
    }

    // Normal app routes (when not partner landing or knowledge base or pitch deck)
    if (isPartnerPage) setIsPartnerPage(false);
    if (isKnowledgeBase) setIsKnowledgeBase(false);
    if (isPitchDeck) setIsPitchDeck(false);

    const isOperatorRoute =
      path === '/tpartner' ||
      path.startsWith('/tpartner') ||
      path.startsWith('/tppartner') ||
      path.startsWith('/operator') ||
      path === '/localoperator' ||
      hash === '#/localoperator' ||
      hash === '#localoperator' ||
      hash === '#/tpartner' ||
      hash === '#tpartner' ||
      search.includes('role=operator') ||
      search.includes('page=operator');

    const isAdminRoute =
      path.startsWith('/admin') ||
      path === '/localadmin' ||
      hash === '#/localadmin' ||
      hash === '#localadmin' ||
      search.includes('role=regional_admin') ||
      search.includes('role=admin');

    const isSuperAdminRoute =
      path.startsWith('/super-admin') ||
      path === '/olegadmin' ||
      path === '/superadmin' ||
      hash === '#/olegadmin' ||
      hash === '#/superadmin' ||
      search.includes('role=super_admin');

    const isProRoute = path.startsWith('/pro');
    const isDashboardRoute = path.startsWith('/dashboard');
    const isServiceRoute = path.startsWith('/services/');

    let routeNeedsLogin = false;
    let expectedRoleForLogin = state.currentRole;

    if (isOperatorRoute) {
      if (state.currentRole !== 'operator') handleRoleChange('operator');
      setExpectedLoginRole('operator');
      expectedRoleForLogin = 'operator';
      routeNeedsLogin = true;
    } else if (isAdminRoute) {
      if (state.currentRole !== 'regional_admin') handleRoleChange('regional_admin');
      setExpectedLoginRole('regional_admin');
      expectedRoleForLogin = 'regional_admin';
      routeNeedsLogin = true;
    } else if (isSuperAdminRoute) {
      if (state.currentRole !== 'super_admin') handleRoleChange('super_admin');
      setExpectedLoginRole('super_admin');
      expectedRoleForLogin = 'super_admin';
      routeNeedsLogin = true;
    } else if (isProRoute) {
      if (state.currentRole !== 'specialist') handleRoleChange('specialist');
      routeNeedsLogin = true;
    } else if (isDashboardRoute) {
      if (state.currentRole !== 'customer') handleRoleChange('customer');
      if (customerView !== 'dashboard') setCustomerView('dashboard');
      routeNeedsLogin = true;
    } else if (isServiceRoute) {
      const rawCat = location.pathname.split('/')[2];
      const cat = normalizeServiceCategory(rawCat);
      if (state.currentRole !== 'customer') handleRoleChange('customer');
      if (customerView !== 'menu') setCustomerView('menu');
      if (cat && state.selectedCategory !== cat) handleSelectCategory(cat);
    } else if (path === '/') {
      if (state.currentUser && state.currentUser.role && state.currentRole !== state.currentUser.role) {
        handleRoleChange(state.currentUser.role);
      }
    }

    if (routeNeedsLogin && !store.getState().currentUser) {
      setShowLoginModal(true);
    }
  }, [location.pathname, location.hash, location.search]);

  // Sync State changes to URL location (without recursive loops)
  useEffect(() => {
    if (isPitchDeck) {
      const expectedPath = pitchDeckLevel === 'tp' ? '/pitch/tp-secret' : pitchDeckLevel === 'rp' ? '/pitch/rp-secret' : '/pitch/investor-secret';
      if (location.pathname !== expectedPath) navigate(expectedPath, { replace: true });
    } else if (isPartnerPage) {
      if (!location.pathname.startsWith('/partner') && !location.hash.includes('partner')) {
        navigate('/partner' + location.hash, { replace: true });
      }
    } else if (isKnowledgeBase) {
      const expectedPath = kbArticleSlug ? `/knowledge-base/${kbArticleSlug}` : '/knowledge-base';
      if (location.pathname !== expectedPath) navigate(expectedPath, { replace: true });
    } else if (state.currentRole === 'specialist') {
      if (location.pathname !== '/pro') navigate('/pro', { replace: true });
    } else if (state.currentRole === 'operator') {
      if (location.pathname.toLowerCase() !== '/tpartner' && location.pathname !== '/operator') navigate('/TPartner', { replace: true });
    } else if (state.currentRole === 'regional_admin') {
      if (location.pathname !== '/admin') navigate('/admin', { replace: true });
    } else if (state.currentRole === 'super_admin') {
      if (location.pathname !== '/super-admin') navigate('/super-admin', { replace: true });
    } else if (state.currentRole === 'customer') {
      if (customerView === 'dashboard') {
        if (location.pathname !== '/dashboard') navigate('/dashboard', { replace: true });
      } else if (state.selectedCategory) {
        const expected = `/services/${encodeURIComponent(state.selectedCategory)}`;
        if (location.pathname !== expected && normalizeServiceCategory(location.pathname.split('/')[2]) !== state.selectedCategory) {
          navigate(expected, { replace: true });
        }
      } else {
        const path = location.pathname.toLowerCase();
        const isSpecialRoute = path.startsWith('/pitch/') || path.startsWith('/knowledge-base') || path.startsWith('/partner') || path === '/become-a-partner';
        if (!isSpecialRoute && location.pathname !== '/' && !location.hash) navigate('/', { replace: true });
      }
    }
  }, [isPitchDeck, pitchDeckLevel, isPartnerPage, isKnowledgeBase, kbArticleSlug, state.currentRole, customerView, state.selectedCategory]);




  if (isPitchDeck) {
    return (
      <div id="pitch-deck-wrapper">
        <PitchDeck key={pitchDeckLevel} initialLevel={pitchDeckLevel} onNavigateHome={() => setIsPitchDeck(false)} />
