            )}

            {state.currentRole === 'operator' && (
              <OperatorDashboard
                jobs={state.jobs}
                onClaimJob={handleClaimJob}
                onOfferJob={handleOfferJob}
                onSelectSpecialist={handleSelectSpecialistForJob}
                onCompleteJob={handleCompleteJob}
                onAddMessage={handleAddMessageOperator}
