          setIsKnowledgeBase(false);
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }}
        onGoHome={() => {
          setIsKnowledgeBase(false);
          setIsPartnerPage(false);
          store.goToHome();
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }}
      />



      {/* Login & Onboarding Modal overlay */}
      {(showLoginModal || (state.currentUser && state.currentUser.isNewUser)) && (
        <div 
          className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/85 backdrop-blur-md p-2 sm:p-6 flex items-start sm:items-center justify-center min-h-screen animate-in fade-in duration-200" 
          id="login-modal-overlay"
        >
          <div className="bg-[#0A1128]/95 backdrop-blur-lg border border-blue-900/30 rounded-2xl sm:rounded-3xl p-4 sm:p-6 w-full max-w-md shadow-[0_20px_50px_rgba(0,0,0,0.7)] relative animate-in zoom-in-95 duration-200 my-auto max-h-[92vh] flex flex-col">
            {/* Show close button - always accessible */}
            <button
              onClick={() => {
                if (state.currentUser && state.currentUser.isNewUser) {
                  store.logout();
                } else {
                  setShowLoginModal(false);
                }
              }}
              className="absolute top-3 right-3 sm:top-4 sm:right-4 text-slate-400 hover:text-white bg-slate-900/80 hover:bg-slate-800 border border-slate-700/50 rounded-full w-8 h-8 flex items-center justify-center font-mono text-sm cursor-pointer transition-colors z-50 shadow-md"
              title={state.currentUser && state.currentUser.isNewUser ? "Exit Onboarding (Logout)" : "Close"}
            >
              ✕
            </button>
            <div className="overflow-y-auto max-h-full pr-0.5 custom-scrollbar">
              <LoginScreen
                expectedRole={expectedLoginRole}
                onLoginSuccess={async (email, phone, name, role, password, isRegistration, dashboardNumber) => {
                  if (role === 'super_admin' && email === 'olegadmin') {
                    if (password !== '162463') {
                      throw new Error('Invalid territorial partner credentials');
                    }
                  }
                  const user = await store.authenticate(email, phone, name, role, password, dashboardNumber, isRegistration);
                  if (!user.isNewUser) {
                    setShowLoginModal(false);
                    handleRoleChange(role);
                    setIsPartnerPage(false);
                  }
                  return user;
                }}
                onOnboardUser={(userId, role, name, phone, city, category) => {
                  store.onboardUser(userId, role as any, name, phone, city, category);
                  setShowLoginModal(false);
                  handleRoleChange(role);
                  setIsPartnerPage(false);
                }}
                currentUser={state.currentUser}
                onLogout={() => store.logout()}
              />
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

import React from 'react';
import { useTranslation } from 'react-i18next';
import { useAutoTranslatedText } from '../hooks/useAITranslation';
import { Languages, Globe, RefreshCw, Sparkles, Check } from 'lucide-react';

interface AITranslatedMessageProps {
  content: string;
  targetLanguage?: string;
  context?: string;
  className?: string;
  showBadge?: boolean;
  inline?: boolean;
}

export const AITranslatedMessage: React.FC<AITranslatedMessageProps> = ({
  content,
  targetLanguage,
  context,
  className = '',
  showBadge = true,
  inline = false
}) => {
  const { t } = useTranslation();
  const {
    displayedText,
    originalText,
    translatedText,
    detectedLanguage,
    isLoading,
    showOriginal,
    toggleShowOriginal,
    isTranslated
  } = useAutoTranslatedText(content, targetLanguage, context);

  if (!content) return null;

  return (
    <div className={`group relative ${inline ? 'inline-block' : 'block'} ${className}`}>
      <span className="whitespace-pre-wrap break-words">{displayedText}</span>

      {/* Loading state indicator */}
      {isLoading && (
        <span className="inline-flex items-center ml-2 text-cyan-400 text-xs animate-pulse" title="AI Translating...">
          <RefreshCw className="w-3 h-3 animate-spin mr-1" />
          <span className="opacity-75">AI</span>
        </span>
      )}

      {/* Translation badge & toggle controls */}
      {!isLoading && showBadge && isTranslated && (
        <div className="mt-1 flex items-center gap-2 text-[11px] text-slate-400 select-none">
          <button
            type="button"
            onClick={toggleShowOriginal}
            className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-cyan-950/40 hover:bg-cyan-900/60 border border-cyan-500/20 text-cyan-300 transition-colors"
            title={showOriginal ? 'Switch to AI Translation' : 'View Original Message'}
          >
            <Globe className="w-3 h-3 text-cyan-400" />
            <span>{showOriginal ? t('chat.showTranslated', 'Ver Traduzido') : t('chat.showOriginal', 'Ver Original')}</span>
          </button>

          {!showOriginal && (
            <span className="text-[10px] text-slate-500 flex items-center gap-1">
              <Sparkles className="w-2.5 h-2.5 text-cyan-400" />
              <span>
                {detectedLanguage.toUpperCase()} → {(targetLanguage || 'pt').toUpperCase()}
              </span>
            </span>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { BookOpen, GraduationCap, ChevronRight, PlayCircle, FileText, ChevronDown } from 'lucide-react';
import { UserRole } from '../types';
import { getSpecialistCurriculum, getOperatorCurriculum } from './academy/curriculumData';
import { SpecialistContent } from './academy/SpecialistContent';
import { OperatorContent } from './academy/OperatorContent';

interface AcademyProps {
  userRole: UserRole;
}

export default function Academy({ userRole }: AcademyProps) {
  const { i18n } = useTranslation();
  const lang = i18n.language === 'pt' ? 'pt' : 'en';
  const isOperatorLevel = userRole === 'operator' || userRole === 'regional_admin' || userRole === 'super_admin';
  const [academyLevel, setAcademyLevel] = useState<'specialist' | 'operator'>('specialist');
  const [activeModule, setActiveModule] = useState<string>('module_1');
  const [expandedSection, setExpandedSection] = useState<string | null>('sec_1_1');

  const specialistCurriculum = getSpecialistCurriculum(lang);
  const operatorCurriculum = getOperatorCurriculum(lang);

  const currentCurriculum = academyLevel === 'specialist' ? specialistCurriculum : operatorCurriculum;
  const currentModuleObj = currentCurriculum.find(m => m.id === activeModule) || currentCurriculum[0];
  const currentSectionObj = currentModuleObj?.sections.find(s => s.id === expandedSection);

  const handleLevelChange = (level: 'specialist' | 'operator') => {
    setAcademyLevel(level);
    if (level === 'specialist') {
      setActiveModule('module_1');
      setExpandedSection('sec_1_1');
    } else {
      setActiveModule('module_op_1');
      setExpandedSection('sec_op_1_1');
    }
  };

  const labels = {
    title: lang === 'pt' ? 'Academia NordBase' : lang === 'ru' ? 'Академия NordBase' : 'NordBase Academy',
    progress: lang === 'pt' ? 'Progresso' : lang === 'ru' ? 'Прогресс' : 'Progress',
    specialistTab: lang === 'pt' ? 'Especialista' : lang === 'ru' ? 'Специалист' : 'Specialist',
    operatorTab: lang === 'pt' ? 'Parceiro Territorial' : lang === 'ru' ? 'Территориальный Партнер' : 'Territory Partner',
    specialistTitle: lang === 'pt' ? 'Academia do Especialista' : lang === 'ru' ? 'Академия Специалистов' : 'Specialist Academy',
    operatorTitle: lang === 'pt' ? 'Academia do Parceiro Territorial' : lang === 'ru' ? 'Академия Территориального Партнера' : 'Territory Partner Academy',
    selectTopic: lang === 'pt' ? 'Selecione um tópico...' : lang === 'ru' ? 'Выберите тему...' : 'Select a topic...',
    breadcrumbRoot: lang === 'pt' ? 'Academia' : lang === 'ru' ? 'Академия' : 'Academy',
    prevLesson: lang === 'pt' ? 'Lição Anterior' : lang === 'ru' ? 'Предыдущий урок' : 'Previous Lesson',
    nextLesson: lang === 'pt' ? 'Próxima Lição' : lang === 'ru' ? 'Следующий урок' : 'Next Lesson',
  };

  return (
    <div className="h-full flex flex-col bg-[#030712] text-slate-200">
      {/* Academy Header */}
      <div className="bg-[#0A1128] border-b border-blue-900/30 p-6 flex items-center justify-between shrink-0">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-cyan-500 to-blue-600 p-0.5">
            <div className="w-full h-full bg-[#0A1128] rounded-[14px] flex items-center justify-center">
              <GraduationCap className="w-6 h-6 text-cyan-400" />
            </div>
          </div>
          <div>
            <h1 className="text-2xl font-display font-black text-white tracking-tight">{labels.title}</h1>
          </div>
        </div>

        <div className="hidden md:flex items-center gap-6">
          <div className="text-right">
            <p className="text-xs text-slate-400 uppercase tracking-wider font-bold">{labels.progress}</p>
            <p className="text-lg font-bold text-white">0%</p>
          </div>
          <div className="w-32 h-2 bg-slate-800 rounded-full overflow-hidden">
            <div className="w-0 h-full bg-cyan-400 rounded-full"></div>
          </div>
        </div>
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar Navigation */}
        <div className="w-80 border-r border-blue-900/30 bg-[#050A1A] overflow-y-auto hidden md:flex flex-col">
          <div className="p-4 border-b border-blue-900/30 mb-4 sticky top-0 bg-[#050A1A] z-10">
            {isOperatorLevel && (
              <div className="flex p-1 bg-slate-900/50 rounded-lg mb-2">
                <button
                  onClick={() => handleLevelChange('specialist')}
                  className={`flex-1 py-1.5 text-xs font-medium rounded-md transition-colors cursor-pointer ${
                    academyLevel === 'specialist' ? 'bg-cyan-500 text-slate-950 font-bold shadow-sm' : 'text-slate-400 hover:text-slate-200'
                  }`}
                >
                  {labels.specialistTab}
                </button>
                <button
                  onClick={() => handleLevelChange('operator')}
                  className={`flex-1 py-1.5 text-xs font-medium rounded-md transition-colors cursor-pointer ${
                    academyLevel === 'operator' ? 'bg-cyan-500 text-slate-950 font-bold shadow-sm' : 'text-slate-400 hover:text-slate-200'
                  }`}
                >
                  {labels.operatorTab}
                </button>
              </div>
            )}
            <h2 className="text-sm font-bold text-slate-400 uppercase tracking-wider">
              {academyLevel === 'specialist' ? labels.specialistTitle : labels.operatorTitle}
            </h2>
          </div>
          <div className="p-4 pt-0 flex-1">
            <div className="space-y-1">
              {currentCurriculum.map((module) => (
                <div key={module.id} className="mb-2">
                  <button
                    onClick={() => setActiveModule(module.id === activeModule ? '' : module.id)}
                    className={`w-full flex items-center justify-between p-3 rounded-xl transition-all font-medium text-sm border cursor-pointer ${
                      activeModule === module.id 
                        ? 'bg-blue-900/30 border-blue-500/30 text-white shadow-[0_0_15px_rgba(37,99,235,0.1)]' 
                        : 'border-transparent text-slate-400 hover:bg-white/5 hover:text-slate-300'
                    }`}
                  >
                    <span className="text-left font-display">{module.title}</span>
                    <ChevronDown className={`w-4 h-4 transition-transform ${activeModule === module.id ? 'rotate-180 text-cyan-400' : ''}`} />
                  </button>

                  {activeModule === module.id && (
                    <div className="mt-1 pl-2 space-y-1 animate-in slide-in-from-top-2 duration-200">
                      {module.sections.map((section) => (
                        <button
                          key={section.id}
                          onClick={() => setExpandedSection(section.id)}
                          className={`w-full flex items-center gap-3 p-2.5 rounded-lg text-xs transition-colors cursor-pointer text-left ${
                            expandedSection === section.id
                              ? 'bg-cyan-500/10 text-cyan-400 font-medium'
                              : 'text-slate-400 hover:text-white hover:bg-white/5'
                          }`}
                        >
                          {expandedSection === section.id ? (
                            <PlayCircle className="w-4 h-4 shrink-0 text-cyan-400" />
                          ) : (
                            <FileText className="w-4 h-4 shrink-0 text-slate-500" />
                          )}
                          <span className="truncate">{section.title}</span>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 bg-[#030712] overflow-y-auto relative">
          {/* Mobile module selector */}
          <div className="md:hidden p-4 border-b border-white/10">
            <select 
              className="w-full bg-[#0A1128] border border-blue-900/30 rounded-xl p-3 text-sm text-white focus:outline-none focus:border-cyan-500"
              value={expandedSection || ''}
              onChange={(e) => {
                const secId = e.target.value;
                setExpandedSection(secId);
                const mod = currentCurriculum.find(m => m.sections.some(s => s.id === secId));
                if (mod) setActiveModule(mod.id);
              }}
            >
              <option value="" disabled>{labels.selectTopic}</option>
              {currentCurriculum.map(m => (
                <optgroup key={m.id} label={m.title}>
                  {m.sections.map(s => (
                    <option key={s.id} value={s.id}>{s.title}</option>
                  ))}
                </optgroup>
              ))}
            </select>
          </div>

          <div className="max-w-3xl mx-auto p-6 md:p-10">
            {/* Breadcrumb */}
            <div className="flex items-center gap-2 text-xs text-slate-500 font-mono mb-6">
              <span>{labels.breadcrumbRoot}</span>
              <ChevronRight className="w-3 h-3" />
              <span>{currentModuleObj?.title || 'Module'}</span>
              <ChevronRight className="w-3 h-3" />
              <span className="text-cyan-400">
                {currentSectionObj?.title || 'Section'}
              </span>
            </div>

            {/* Content text */}
            <div className="prose prose-invert prose-slate max-w-none">
              {academyLevel === 'specialist' ? (
                <SpecialistContent expandedSection={expandedSection} lang={lang} currentSectionTitle={currentSectionObj?.title} />
              ) : (
                <OperatorContent expandedSection={expandedSection} lang={lang} currentSectionTitle={currentSectionObj?.title} />
              )}
            </div>

            {/* Navigation Buttons */}
            <div className="flex items-center justify-between mt-12 pt-6 border-t border-blue-900/30">
              <button 
                onClick={() => {
                  // Navigate to previous section
                  const allSections = currentCurriculum.flatMap(m => m.sections);
                  const currentIndex = allSections.findIndex(s => s.id === expandedSection);
                  if (currentIndex > 0) {
                    const prevSec = allSections[currentIndex - 1];
                    setExpandedSection(prevSec.id);
                    const mod = currentCurriculum.find(m => m.sections.some(s => s.id === prevSec.id));
                    if (mod) setActiveModule(mod.id);
                  }
                }}
                className="px-5 py-2.5 rounded-xl border border-blue-900/50 text-slate-300 hover:text-white hover:bg-white/5 transition-colors text-sm font-medium cursor-pointer"
              >
                {labels.prevLesson}
              </button>
              <button 
                onClick={() => {
                  // Navigate to next section
                  const allSections = currentCurriculum.flatMap(m => m.sections);
                  const currentIndex = allSections.findIndex(s => s.id === expandedSection);
                  if (currentIndex >= 0 && currentIndex < allSections.length - 1) {
                    const nextSec = allSections[currentIndex + 1];
                    setExpandedSection(nextSec.id);
                    const mod = currentCurriculum.find(m => m.sections.some(s => s.id === nextSec.id));
                    if (mod) setActiveModule(mod.id);
                  }
                }}
                className="px-6 py-2.5 rounded-xl bg-cyan-500 text-slate-950 hover:bg-cyan-400 transition-colors text-sm font-bold shadow-[0_0_15px_rgba(6,182,212,0.3)] cursor-pointer"
              >
                {labels.nextLesson}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { MapPin, Search, Loader2, X, Check } from 'lucide-react';

interface AddressAutocompleteProps {
  userLocation?: { lat: number, lon: number } | null;
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
  required?: boolean;
  multiline?: boolean;
  rows?: number;
}

export function AddressAutocomplete({ 
  value, 
  onChange, 
  placeholder = "", 
  className = "", 
  required = false, 
  userLocation = null,
  multiline = false,
  rows = 2
}: AddressAutocompleteProps) {
  const { t } = useTranslation();
  const [query, setQuery] = useState(value);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [isConfirmed, setIsConfirmed] = useState(!!value);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const skipNextFetch = useRef(false);

  useEffect(() => {
    if (value !== query) {
      setQuery(value);
      setIsConfirmed(!!value);
    }
  }, [value]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (query.length < 3) {
      setSuggestions([]);
      setIsOpen(false);
      return;
    }

    if (skipNextFetch.current) {
      skipNextFetch.current = false;
      return;
    }

    setLoading(true);
    setIsOpen(true);

    const timer = setTimeout(async () => {
      try {
        const res = await fetch(`https://photon.komoot.io/api/?q=${encodeURIComponent(query)}&limit=5${userLocation ? `&lat=${userLocation.lat}&lon=${userLocation.lon}` : '&lat=39.3999&lon=-8.2245'}`);
        const data = await res.json();

        if (data.features) {
          const formattedSuggestions = data.features.map((feature: any) => {
            const props = feature.properties;
            const parts = [
              props.name,
              props.housenumber,
              props.street,
              props.district,
              props.city,
              props.postcode
            ].filter(Boolean);

            // Deduplicate parts
            return Array.from(new Set(parts)).join(', ');
          });
          setSuggestions(formattedSuggestions);
        } else {
          setSuggestions([]);
        }
      } catch (err) {
        console.error("Failed to fetch addresses", err);
        setSuggestions([]);
      } finally {
        setLoading(false);
      }
    }, 500);

    return () => clearTimeout(timer);
  }, [query]);

  const handleSelect = (suggestion: string) => {
    skipNextFetch.current = true;
    setQuery(suggestion);
    onChange(suggestion);
    setIsConfirmed(true);
    setIsOpen(false);
  };

  const handleConfirm = () => {
    if (query.trim()) {
      setIsConfirmed(true);
      onChange(query);
      setIsOpen(false);
    }
  };

  return (
    <div ref={wrapperRef} className={`relative w-full ${className}`}>
      {multiline ? (
        <>
          <div className="relative w-full">
            <div className="absolute left-3.5 top-3.5 pointer-events-none z-10">
              <MapPin className="h-4 sm:h-5 w-4 sm:w-5 text-cyan-500" />
            </div>

            <textarea
              rows={rows}
              required={required}
              placeholder={placeholder || t('address.placeholder')}
              value={query}
              onChange={(e) => {
                setQuery(e.target.value);
                onChange(e.target.value);
                setIsConfirmed(false);
              }}
              onFocus={() => {
                if (query.length >= 3) setIsOpen(true);
              }}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleConfirm();
                }
              }}
              className="w-full pl-10 pr-10 py-3 bg-slate-950/80 border border-blue-900/40 rounded-xl text-xs sm:text-sm font-normal text-white placeholder-slate-500 focus:outline-none focus:border-cyan-400/60 focus:ring-1 focus:ring-cyan-400/50 transition-all font-sans shadow-inner resize-none leading-relaxed min-h-[75px]"
            />

            {/* Top-right quick action buttons */}
            <div className="absolute right-3 top-3 flex items-center gap-1 z-10">
              {!query && (
                <button
                  onClick={() => {
                    if (navigator.geolocation) {
                      setLoading(true);
                      navigator.geolocation.getCurrentPosition(
                        async (pos) => {
                          try {
                            const res = await fetch(`https://photon.komoot.io/api/?q=Portugal&limit=1&lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`);
                            const data = await res.json();
                            if (data.features && data.features.length > 0) {
                              const props = data.features[0].properties;
                              const parts = [props.name, props.street, props.city].filter(Boolean);
                              const suggested = Array.from(new Set(parts)).join(', ');
                              setQuery(suggested);
                              onChange(suggested);
                              setIsConfirmed(true);
                            }
                          } catch (e) {
                            console.error(e);
                          } finally {
                            setLoading(false);
                          }
                        },
                        () => setLoading(false)
                      );
                    }
                  }}
                  className="text-cyan-500 hover:text-cyan-400 bg-cyan-500/10 p-1 rounded transition-colors border border-cyan-500/20"
                  type="button"
                  title={t("address.locateMe")}
                >
                  <MapPin className="h-3.5 w-3.5" />
                </button>
              )}
              {query && (
                <button
                  onClick={() => {
                    setQuery('');
                    onChange('');
                    setIsConfirmed(false);
                    setIsOpen(false);
                  }}
                  className="text-slate-400 hover:text-white transition-colors p-1 rounded bg-slate-900/60 border border-slate-800 cursor-pointer"
                  type="button"
                  title={t('address.clearAddress', 'Clear address')}
                >
                  <X className="h-3.5 w-3.5" />
                </button>
              )}
            </div>
          </div>
        </>
      ) : (
        <div className="relative w-full">
          <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none z-10">
            <MapPin className="h-5 w-5 text-cyan-500" />
          </div>

          <input
            type="text"
            required={required}
            placeholder={placeholder || t('address.placeholder')}
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              onChange(e.target.value);
              setIsConfirmed(false);
            }}
            onFocus={() => {
              if (query.length >= 3) setIsOpen(true);
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                handleConfirm();
              }
            }}
            className="w-full pl-11 pr-20 py-3.5 bg-slate-950/80 border border-blue-900/40 rounded-2xl text-sm sm:text-base text-white placeholder-slate-400 focus:outline-none focus:border-cyan-400/50 focus:ring-1 focus:ring-cyan-400/50 transition-all font-sans shadow-lg shadow-black/20"
          />

          <div className="absolute inset-y-0 right-0 flex items-center pr-3 gap-1.5 z-10">
            {!query && (
              <button
                onClick={() => {
                  if (navigator.geolocation) {
                    setLoading(true);
                    navigator.geolocation.getCurrentPosition(
                      async (pos) => {
                        try {
                          const res = await fetch(`https://photon.komoot.io/api/?q=Portugal&limit=1&lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`);
                          const data = await res.json();
                          if (data.features && data.features.length > 0) {
                            const props = data.features[0].properties;
                            const parts = [props.name, props.street, props.city].filter(Boolean);
                            const suggested = Array.from(new Set(parts)).join(', ');
                            setQuery(suggested);
                            onChange(suggested);
                            setIsConfirmed(true);
                          }
                        } catch (e) {
                          console.error(e);
                        } finally {
                          setLoading(false);
                        }
                      },
                      () => setLoading(false)
                    );
                  }
                }}
                className="text-cyan-500 hover:text-cyan-400 bg-cyan-500/10 p-1.5 rounded-lg transition-colors border border-cyan-500/20"
                type="button"
                title={t("address.locateMe")}
              >
                <MapPin className="h-4 w-4" />
              </button>
            )}
            {query && (
              <button
                onClick={() => {
                  setQuery('');
                  onChange('');
                  setIsConfirmed(false);
                  setIsOpen(false);
                }}
                className="text-slate-400 hover:text-white transition-colors p-1 cursor-pointer"
                type="button"
                title={t('address.clearAddress', 'Clear address')}
              >
                <X className="h-4 w-4" />
              </button>
            )}
          </div>
        </div>
      )}

      {/* Prominent Action / Confirmation Status Box below field */}
      {query.trim() && !isConfirmed && (
        <div className="mt-2 flex items-center justify-between gap-3 p-2.5 bg-gradient-to-r from-blue-950/90 via-slate-900 to-slate-950 border border-cyan-500/50 rounded-xl shadow-lg">
          <div className="flex items-center gap-2 min-w-0 pl-1">
            <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse shrink-0"></span>
            <span className="text-xs text-slate-200 font-medium truncate">
              {t('address.confirmHint', "Address entered. Click 'Confirm' to pin.")}
            </span>
          </div>
          <button
            onClick={handleConfirm}
            type="button"
            className="bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-400 hover:to-blue-400 text-slate-950 font-black px-4 py-2 rounded-lg text-xs transition-all shadow-lg shadow-cyan-500/25 active:scale-95 cursor-pointer flex items-center gap-1.5 shrink-0 border-0"
          >
            <Check className="h-4 w-4 stroke-[3]" />
            <span>{t('address.confirm', 'Confirm Address')}</span>
          </button>
        </div>
      )}

      {query.trim() && isConfirmed && (
        <div className="mt-2 flex items-center justify-between gap-2 px-3 py-2 bg-emerald-950/50 border border-emerald-500/40 rounded-xl text-xs text-emerald-300 font-bold shadow-sm animate-in fade-in duration-200">
          <div className="flex items-center gap-2 min-w-0">
            <Check className="h-4 w-4 text-emerald-400 shrink-0 stroke-[3]" />
            <span className="truncate">{t('address.savedHint', 'Address confirmed!')}</span>
          </div>
          <button
            onClick={() => setIsConfirmed(false)}
            type="button"
            className="text-slate-400 hover:text-white text-[11px] font-bold px-2 py-0.5 rounded bg-slate-900 border border-slate-700 cursor-pointer shrink-0 ml-2"
          >
            {t('address.edit', 'Edit')}
          </button>
        </div>
      )}

      {/* Autocomplete Dropdown Overlay */}
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-slate-900 border border-blue-900/60 rounded-2xl overflow-hidden shadow-2xl z-50 animate-in fade-in slide-in-from-top-2">
          {loading ? (
            <div className="flex items-center gap-3 px-5 py-4 text-slate-400 text-sm">
              <Loader2 className="h-4 w-4 animate-spin text-cyan-500" />
              {t('address.searching', 'Searching addresses...')}
            </div>
          ) : (
            <div>
              {suggestions.length > 0 && (
                <ul className="py-2 divide-y divide-slate-800/40">
                  {suggestions.map((suggestion, idx) => (
                    <li key={idx}>
                      <button
                        onClick={() => handleSelect(suggestion)}
                        className="w-full text-left px-5 py-3 hover:bg-slate-800/60 flex items-center gap-3 text-sm text-slate-200 transition-colors cursor-pointer"
                        type="button"
                      >
                        <Search className="h-4 w-4 text-slate-500 flex-shrink-0" />
                        <span className="truncate">{suggestion}</span>
                      </button>
                    </li>
                  ))}
                </ul>
              )}

              {/* Explicit option to use exactly what the user typed */}
              {query.trim().length >= 2 && (
                <div className="p-2 border-t border-blue-900/40 bg-slate-950/80">
                  <button
                    onClick={() => handleSelect(query)}
                    className="w-full text-left px-4 py-3 rounded-xl hover:bg-cyan-950/60 bg-slate-900 border border-cyan-500/40 flex items-center justify-between gap-3 text-xs sm:text-sm text-cyan-300 font-bold transition-all cursor-pointer shadow-md active:scale-98"
                    type="button"
                  >
                    <div className="flex items-center gap-2 truncate">
                      <Check className="h-4 w-4 text-cyan-400 shrink-0 stroke-[3]" />
                      <span className="truncate">{t('address.useEntered', 'Use entered address:')} "{query}"</span>
                    </div>
                    <span className="text-[10px] bg-cyan-500 text-slate-950 px-2 py-1 rounded-lg font-black uppercase tracking-wider shrink-0">
                      {t('address.confirm', 'Confirm')}
                    </span>
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from "react";
import {
  Job,
  Specialist,
  AuthUser,
  SupportTicket,
} from "../types";
import {
  ShieldAlert,
  Globe,
  Shield,
  AlertTriangle,
  UserCheck,
  UserX,
  Search,
  MessageCircle,
  Inbox,
  Send,
  ChevronDown,
  ChevronUp,
  Edit2,
  Lock,
  Phone,
  Mail,
  MapPin,
  GraduationCap,
  Sparkles,
  Building2,
} from "lucide-react";
import { PORTUGAL_GEO } from "../lib/geo";
import { LocationSearchInput } from "./LocationSearchInput";
import Academy from "./Academy";
import { KnowledgeEvolutionPanel } from "./KnowledgeEvolutionPanel";
