  const [agentFilter, setAgentFilter] = useState<'all' | AgentType | 'e2e'>('all');

  const handleRunSuite = async () => {
    setIsRunning(true);
    setLogs(['[Test Harness] Initializing Complete Multi-Agent Suite (Packs 1 & 2)...']);
    setScenarios([]);
    setReport(null);

    try {
      const res = await SimulationRunner.runFullMultiAgentSuite((currentScenarios, logMsg) => {
        setScenarios(currentScenarios);
        setLogs(prev => [...prev, `[${new Date().toLocaleTimeString()}] ${logMsg}`]);
      }, true);
      setReport(res);
      setScenarios(res.scenarios);
      if (res.scenarios.length > 0) {
        setSelectedScenarioId(res.scenarios[0].id);
      }
    } catch (err: any) {
      setLogs(prev => [...prev, `[ERROR] Simulation halted: ${err.message}`]);
