                            onError={(e) => {
                              e.currentTarget.src = '/portimao_tp.jpg';
                            }}
                          />
                          <div className="text-left">
                            <span className="text-[9px] font-mono text-cyan-400 block uppercase tracking-wider font-bold">{lang === 'pt' ? 'Parceiro Territorial PT' : lang === 'ru' ? 'Территориальный Партнер' : 'Territorial Partner TP'}</span>
                            <span className="text-xs font-bold text-white block">
