  const [isUploading, setIsUploading] = useState(false);
  const [isDragOver, setIsDragOver] = useState(false);
  const [selectedOperatorId, setSelectedOperatorId] = useState<string | null>(null);
  const [formErrors, setFormErrors] = useState<{
    customerName?: string;
    localPhone?: string;
    specificLocation?: string;
    description?: string;
  }>({});

  React.useEffect(() => {
    if (currentUser) {
      if (currentUser.name && !customerName) setCustomerName(currentUser.name);
      if (currentUser.phone && !localPhone) {
        setLocalPhone(currentUser.phone.replace(/^\+351\s*/, ''));
      }
    }
  }, [currentUser]);

  // Local search query state
  const [searchQuery, setSearchQuery] = useState('');

  // Local chat message state
  const [typedMessage, setTypedMessage] = useState('');
  const [activeChatChannel, setActiveChatChannel] = useState<'customer_operator' | 'customer_specialist'>('customer_operator');
  const [chatUploading, setChatUploading] = useState(false);

  // Category and Specialty Selection State
  const [selectedSpecialty, setSelectedSpecialty] = useState<string | null>(null);

  // Reset specialty when parent resets selectedCategory
  useEffect(() => {
    if (!selectedCategory) {
      setSelectedSpecialty(null);
    }
  }, [selectedCategory]);

  // Find currently submitted job details if any
  const currentJob = jobs.find((j) => j.id === submittedJobId);

  // Find best geo match and dispatcher dynamically based on the specific location input
  const geoMatch = specificLocation ? findBestGeoMatch(specificLocation) : null;
  const matchedDispatcher = geoMatch ? getDispatcherForGeo(geoMatch.city, geoMatch.region) : null;

  // Find matching registered operators from the DB/Store matching this city or Algarve region
  const activeCity = geoMatch?.city || store.getState().selectedCity || 'Portimão';
  const allUsers = store.getState().users || [];

  // Real operators from the database/store
  const realOperators = allUsers.filter(u => 
    u.role === 'operator' || u.role === 'regional_admin' || u.role === 'super_admin'
  );

  // Filter operators by city to prioritize those in the active city/region
  let combinedOperators: any[] = realOperators.filter(u => 
    u.city && (u.city.toLowerCase().includes(activeCity.toLowerCase()) || activeCity.toLowerCase().includes(u.city.toLowerCase()))
  );

  // Fallback to all operators if none found in the specific city
  if (combinedOperators.length === 0) {
    combinedOperators = realOperators;
  }

  // Pre-select first operator if not selected yet
  useEffect(() => {
    if (combinedOperators.length > 0 && (!selectedOperatorId || !combinedOperators.some(op => op.id === selectedOperatorId))) {
      setSelectedOperatorId(combinedOperators[0].id);
    }
  }, [combinedOperators, selectedOperatorId]);

  const selectedOperator = combinedOperators.find(op => op.id === selectedOperatorId) || combinedOperators[0];

