                          onError={(e) => {
                            e.currentTarget.src = '/portimao_tp.jpg';
                          }}
                        />
                        <div className="text-left min-w-0 flex-1">
                          <p className="text-[10px] font-mono text-cyan-400 uppercase tracking-widest font-bold">{t('flow.tpIdentified')}</p>
                          <p className="text-xs sm:text-sm font-bold text-white leading-tight truncate">{opName}</p>
                          <p className="text-[11px] text-slate-300 truncate">{t('flow.tpFor')} {geoMatch?.fullName || activeCity || 'Portimão (Algarve)'}</p>
                        </div>
                      </div>
                    );
                  })()
