                <PhoneCall className="w-5 h-5 animate-pulse" />
              </div>
              <div>
                <p className="text-xs font-mono font-bold text-cyan-400 uppercase tracking-wide">
                  {lang === 'en' ? 'Need Immediate Service Dispatch?' : 'Precisa de Despacho Imediato de Serviço?'}
                </p>
                <p className="text-sm font-bold text-white">
                  {lang === 'en' ? 'Connect with certified local technicians in < 3 mins' : 'Ligação direta a técnicos certificados em < 3 mins'}
                </p>
              </div>
            </div>

            <button
