          {selectedArticle.importantInfoNeeded?.[lang] && selectedArticle.importantInfoNeeded[lang].length > 0 && selectedArticle.unnecessaryInfo?.[lang] && selectedArticle.unnecessaryInfo[lang].length > 0 && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 my-6">
              <div className="p-5 rounded-2xl bg-emerald-950/30 border border-emerald-500/30">
                <div className="flex items-center gap-2 text-emerald-400 font-bold text-sm mb-3">
                  <CheckCircle2 className="w-5 h-5 text-emerald-400 shrink-0" />
                  <span>{lang === 'en' ? 'Crucial Information to Provide' : 'Informação Crucial a Fornecer'}</span>
                </div>
                <ul className="space-y-2 text-xs text-slate-300">
                  {selectedArticle.importantInfoNeeded[lang].map((item, idx) => (
                    <li key={idx} className="flex items-start gap-2">
                      <span className="text-emerald-400 font-bold">•</span>
                      <span>{item}</span>
                    </li>
                  ))}
                </ul>
              </div>

              <div className="p-5 rounded-2xl bg-slate-900/60 border border-slate-700/50">
                <div className="flex items-center gap-2 text-slate-400 font-bold text-sm mb-3">
                  <XCircle className="w-5 h-5 text-slate-500 shrink-0" />
