          <div className="space-y-6 p-6 sm:p-8 rounded-3xl bg-slate-950/80 border border-white/10 shadow-xl">
            {selectedArticle.contentSections.map((sec, idx) => (
              <div key={idx} className="space-y-2 border-b border-white/5 pb-6 last:border-b-0 last:pb-0">
