      )}

      {/* Tab 2: Approved Glossary */}
      {activeTab === 'glossary' && (
        <div className="mt-6 space-y-4">
          <div className="flex items-center gap-3">
            <div className="relative flex-1">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
              <input
