interface LocationSelectorProps {
  onSelect: (location: string) => void;
  onClose: () => void;
}

export function LocationSelector({ onSelect, onClose }: LocationSelectorProps) {
  const [mode, setMode] = useState<'keypad' | 'search'>('keypad');
  const [keypadInput, setKeypadInput] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [recentLocations, setRecentLocations] = useState<string[]>([]);

  // Ref for search input auto-focus
  const searchInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Load recent locations
    const stored = localStorage.getItem('nordbase_recent_locations');
    if (stored) {
      try {
        setRecentLocations(JSON.parse(stored));
      } catch (e) {
        /* ignore invalid json */
      }
    }
  }, []);

  useEffect(() => {
    if (mode === 'search' && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  }, [mode]);

  const handleSelect = (location: string) => {
    // Save to recents
    const newRecents = [location, ...recentLocations.filter(l => l !== location)].slice(0, 3);
    localStorage.setItem('nordbase_recent_locations', JSON.stringify(newRecents));
    setRecentLocations(newRecents);
    onSelect(location);
  };

  // Handle Keypad logic
  const currentRegion = useMemo(() => {
    if (!keypadInput) return null;
    return PORTUGAL_GEO.find(r => keypadInput.startsWith(r.id)) || null;
  }, [keypadInput]);

  const currentCity = useMemo(() => {
    if (!currentRegion || keypadInput.length < 2) return null;
    return currentRegion.cities.find(c => keypadInput.startsWith(c.id)) || null;
  }, [keypadInput, currentRegion]);

  const currentDistrict = useMemo(() => {
    if (!currentCity || !currentCity.districts || keypadInput.length < 3) return null;
    return currentCity.districts.find(d => keypadInput === d.id) || null;
  }, [keypadInput, currentCity]);

  // Determine what list to show in keypad mode
  const keypadList = useMemo(() => {
    if (!keypadInput) return PORTUGAL_GEO.map(r => ({ ...r, type: 'region' as const }));
    if (currentRegion && keypadInput === currentRegion.id) {
      return currentRegion.cities.map(c => ({ ...c, type: 'city' as const }));
    }
    if (currentCity && keypadInput === currentCity.id) {
      if (currentCity.districts && currentCity.districts.length > 0) {
        return currentCity.districts.map(d => ({ ...d, type: 'district' as const }));
      }
    }
    return [];
  }, [keypadInput, currentRegion, currentCity]);

  const handleKeypadPress = (key: string) => {
    if (key === 'clear') {
      setKeypadInput(prev => prev.slice(0, -1));
      return;
    }

    const nextInput = keypadInput + key;
    setKeypadInput(nextInput);

    // Auto-select if it's a complete leaf node match
    const r = PORTUGAL_GEO.find(r => nextInput.startsWith(r.id));
    if (r) {
      const c = r.cities.find(c => nextInput.startsWith(c.id));
      if (c && nextInput === c.id) {
        if (!c.districts || c.districts.length === 0) {
          handleSelect(`${c.name} (${r.name})`);
          return;
        }
      }
      if (c && c.districts) {
        const d = c.districts.find(d => nextInput === d.id);
        if (d) {
          handleSelect(`${c.name}, ${d.name} (${r.name})`);
          return;
        }
      }
    }
  };

  const handleListItemClick = (item: any) => {
    if (item.type === 'region') {
      setKeypadInput(item.id);
    } else if (item.type === 'city') {
      setKeypadInput(item.id);
      if (!item.districts || item.districts.length === 0) {
        handleSelect(`${item.name} (${currentRegion?.name})`);
      }
    } else if (item.type === 'district') {
      setKeypadInput(item.id);
      handleSelect(`${currentCity?.name}, ${item.name} (${currentRegion?.name})`);
    }
  };

  // Search logic
  const searchResults = useMemo(() => {
    if (!searchQuery.trim()) return [];
    const q = searchQuery.toLowerCase();
    return FLATTENED_GEO.filter(item => 
      item.fullName.toLowerCase().includes(q)
    ).slice(0, 10);
  }, [searchQuery]);

  return (
    <div className="fixed inset-0 z-[100] bg-slate-950 flex flex-col font-sans animate-in slide-in-from-bottom-4 duration-300 text-white">
      {/* Header */}
      <div className="flex items-center justify-between p-5 border-b border-white/5 bg-[#030712]">
        <h2 className="text-lg font-bold tracking-tight">Select Location</h2>
        <button onClick={onClose} className="p-2 bg-white/5 rounded-full hover:bg-white/10 transition-colors">
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Mode Switcher */}
      <div className="flex px-4 py-3 bg-[#030712] border-b border-white/5">
        <div className="flex w-full bg-white/5 rounded-xl p-1">
          <button 
            className={`flex-1 py-2.5 text-sm font-semibold rounded-lg transition-all ${mode === 'keypad' ? 'bg-[#030712] text-white shadow-sm ring-1 ring-white/10' : 'text-slate-400 hover:text-white'}`}
            onClick={() => setMode('keypad')}
          >
            Fast Keypad
          </button>
          <button 
            className={`flex-1 py-2.5 text-sm font-semibold rounded-lg transition-all ${mode === 'search' ? 'bg-[#030712] text-white shadow-sm ring-1 ring-white/10' : 'text-slate-400 hover:text-white'}`}
            onClick={() => setMode('search')}
          >
            Text Search
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col bg-[#030712] overflow-hidden">

        {mode === 'keypad' ? (
          <div className="flex-1 flex flex-col h-full">

            {/* Recent Locations (Show only if no input) */}
            {!keypadInput && recentLocations.length > 0 && (
              <div className="px-4 py-3 border-b border-white/5 bg-slate-900/30">
                <div className="text-xs font-semibold text-slate-500 mb-2 uppercase tracking-wider">Recent</div>
                <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">
                  {recentLocations.map(loc => (
                    <button 
                      key={loc}
                      onClick={() => handleSelect(loc)}
                      className="px-3 py-1.5 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-sm whitespace-nowrap flex items-center gap-1.5 transition-colors"
                    >
                      <Clock className="w-3.5 h-3.5 text-cyan-400" />
                      {loc}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Breadcrumb / Input Display */}
            <div className="px-4 py-3 bg-[#030712] border-b border-white/5 min-h-[64px] flex items-center">
              {keypadInput ? (
                <div className="flex items-center gap-2 text-sm flex-wrap">
                  {currentRegion && (
                    <span className="bg-slate-800 text-white px-2.5 py-1.5 rounded-lg font-medium flex items-center gap-1.5 cursor-pointer hover:bg-slate-700" onClick={() => setKeypadInput('')}>
                      {currentRegion.name} <X className="w-3 h-3 text-slate-400" />
                    </span>
                  )}
                  {currentCity && (
                    <>
                      <ChevronRight className="w-4 h-4 text-slate-600" />
                      <span className="bg-slate-800 text-white px-2.5 py-1.5 rounded-lg font-medium flex items-center gap-1.5 cursor-pointer hover:bg-slate-700" onClick={() => setKeypadInput(currentRegion!.id)}>
                        {currentCity.name} <X className="w-3 h-3 text-slate-400" />
                      </span>
                    </>
                  )}
                  {currentDistrict && (
                    <>
                      <ChevronRight className="w-4 h-4 text-slate-600" />
                      <span className="bg-cyan-950/50 text-cyan-400 border border-cyan-900/50 px-2.5 py-1.5 rounded-lg font-medium">
                        {currentDistrict.name}
                      </span>
                    </>
                  )}
                  {/* Blinking cursor */}
                  <span className="w-1.5 h-5 bg-cyan-400 animate-pulse ml-1 rounded-full"></span>
                </div>
              ) : (
                <div className="text-slate-500 text-sm flex items-center gap-2">
                  <MapPin className="w-4 h-4" />
                  <span>Select Region (Type 1-7)</span>
                  <span className="w-1.5 h-5 bg-slate-600 animate-pulse ml-1 rounded-full"></span>
                </div>
              )}
            </div>

            {/* List View */}
            <div className="flex-1 overflow-y-auto px-4 py-3">
              <div className={keypadList[0]?.type === 'region' ? "grid grid-cols-3 gap-2.5 sm:gap-4" : "grid grid-cols-1 gap-2"}>
                {keypadList.map(item => {
                  if (item.type === 'region') {
                    const meta = REGION_METADATA[item.id] || { icon: MapPin, color: 'border-blue-900/30', bgGlow: 'bg-slate-900/50 text-slate-400', desc: 'Portugal Region', text: 'text-blue-400' };
                    const Icon = meta.icon;
                    return (
                      <button 
                        key={item.id} 
                        className={`group relative aspect-[0.85] sm:aspect-square p-2.5 sm:p-5 bg-slate-900/60 border ${meta.color} rounded-[1.25rem] sm:rounded-[2rem] transition-all hover:scale-[1.03] active:scale-90 text-center flex flex-col items-center justify-between w-full cursor-pointer overflow-hidden`}
                        onClick={() => handleListItemClick(item)}
                      >
                        {/* Background glow decoration */}
                        <div className="absolute inset-0 bg-slate-950/20 opacity-30 group-hover:opacity-10 transition-opacity" />
                        <div className="absolute -right-4 -bottom-4 w-12 h-12 bg-current opacity-[0.02] rounded-full blur-md group-hover:opacity-[0.05] transition-opacity pointer-events-none" />

                        {/* Top Accent Spacer */}
                        <div className="w-full flex justify-center z-10 opacity-0 group-hover:opacity-100 transition-all duration-300">
                          <span className="text-[8px] sm:text-[9px] text-cyan-400/80 font-mono tracking-widest uppercase font-black">Select</span>
                        </div>

                        {/* Elegant Centered Large Icon */}
                        <div className="my-auto flex flex-col items-center justify-center z-10">
                          <div className={`p-3.5 sm:p-5 rounded-full ${meta.bgGlow} border border-white/5 shadow-[0_0_20px_rgba(255,255,255,0.02)] transition-all duration-300 group-hover:scale-110 group-hover:brightness-110`}>
                            <Icon className="w-6 h-6 sm:w-10 sm:h-10 stroke-[1.5]" />
                          </div>
                        </div>

                        <div className="w-full text-center z-10 mt-auto">
                          <span className="block font-black text-white text-[10px] sm:text-sm tracking-tight group-hover:text-cyan-300 transition-colors uppercase leading-none truncate">
                            {item.name}
                          </span>
                        </div>
                      </button>
                    );
                  }

                  // City or District layout
                  return (
                    <button 
                      key={item.id} 
                      className="group flex items-center justify-between p-3.5 bg-slate-900/40 hover:bg-[#111c3d]/70 border border-blue-950/50 hover:border-cyan-500/50 rounded-xl transition-all text-left cursor-pointer shadow-sm active:scale-[0.98]"
                      onClick={() => handleListItemClick(item)}
                    >
                      <div className="flex items-center gap-3">
                        <div className="w-9 h-9 rounded-xl bg-blue-950/40 text-cyan-400 flex items-center justify-center border border-blue-900/20 group-hover:bg-cyan-500/10 transition-colors shrink-0">
                          <MapPin className="w-4 h-4 text-cyan-400 stroke-[2]" />
                        </div>
                        <div>
                          <span className="font-bold text-slate-200 group-hover:text-white transition-colors">{item.name}</span>
                        </div>
                      </div>
                      {item.type !== 'district' && (!item.districts || item.districts.length > 0) && (
                        <ChevronRight className="w-4 h-4 text-slate-600 group-hover:text-cyan-400 group-hover:translate-x-0.5 transition-all" />
                      )}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Numeric Keypad (Bottom Fixed) */}
            <div className="bg-[#030712] p-4 pb-8 border-t border-white/5 shrink-0">
              <div className="grid grid-cols-3 gap-3 max-w-[320px] mx-auto">
                {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                  <button 
                    key={num} 
                    className="h-14 sm:h-16 bg-slate-900 hover:bg-slate-800 active:bg-slate-700 rounded-2xl flex items-center justify-center text-2xl font-medium transition-all"
                    onClick={() => handleKeypadPress(num.toString())}
                  >
                    {num}
                  </button>
                ))}
                <button className="h-14 sm:h-16 bg-transparent flex items-center justify-center text-2xl font-medium opacity-20 cursor-not-allowed">
                  *
                </button>
                <button 
                  className="h-14 sm:h-16 bg-slate-900 hover:bg-slate-800 active:bg-slate-700 rounded-2xl flex items-center justify-center text-2xl font-medium transition-all"
                  onClick={() => handleKeypadPress('0')}
                >
                  0
                </button>
                <button 
                  className="h-14 sm:h-16 bg-transparent hover:bg-red-950/30 active:bg-red-900/50 rounded-2xl flex items-center justify-center transition-all text-slate-500 hover:text-red-400"
                  onClick={() => handleKeypadPress('clear')}
                  disabled={!keypadInput}
                >
                  <Delete className="w-6 h-6" />
                </button>
              </div>
            </div>

          </div>
        ) : (
          <div className="flex-1 flex flex-col h-full">
            {/* Search Input */}
            <div className="p-4 border-b border-white/5 bg-[#030712]">
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input 
                  ref={searchInputRef}
                  type="text" 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="E.g. Faro, Albufeira..."
                  className="w-full bg-slate-900/50 border border-slate-800 rounded-xl py-4 pl-12 pr-4 text-white placeholder-slate-500 focus:outline-none focus:border-cyan-500/50 focus:ring-1 focus:ring-cyan-500/50 transition-all text-lg"
                />
                {searchQuery && (
                  <button 
                    className="absolute right-4 top-1/2 -translate-y-1/2 p-1 bg-slate-800 rounded-full text-slate-400 hover:text-white"
                    onClick={() => setSearchQuery('')}
                  >
                    <X className="w-4 h-4" />
                  </button>
                )}
              </div>
            </div>

            {/* Search Results */}
            <div className="flex-1 overflow-y-auto p-2">
              {searchResults.length > 0 ? (
                <div className="space-y-1">
                  {searchResults.map(result => (
                    <button 
                      key={result.id}
                      className="w-full flex items-center gap-4 p-4 hover:bg-white/5 rounded-xl transition-colors text-left group"
                      onClick={() => handleSelect(result.fullName)}
                    >
                      <div className="w-10 h-10 rounded-full bg-slate-900 flex items-center justify-center text-slate-500 group-hover:text-cyan-400 group-hover:bg-cyan-950/30 transition-colors shrink-0">
                        <MapPin className="w-5 h-5" />
                      </div>
                      <div>
                        <div className="font-medium text-slate-200 text-lg">{result.shortName}</div>
                        <div className="text-sm text-slate-500">{result.region}</div>
                      </div>
                    </button>
                  ))}
                </div>
              ) : searchQuery ? (
                <div className="text-center p-8 text-slate-500 mt-10">
                  <MapPin className="w-10 h-10 mx-auto mb-4 opacity-20" />
                  <p className="text-lg">No locations found matching "{searchQuery}"</p>
                </div>
              ) : (
                <div className="text-center p-8 text-slate-500 mt-10">
                  <Search className="w-10 h-10 mx-auto mb-4 opacity-20" />
                  <p className="text-lg">Type a city or district name</p>
                </div>
              )}
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { AuthUser, ServiceCategory, UserRole } from '../types';
import { validatePhone } from '../lib/validation';
import NordBaseLogo from './NordBaseLogo';
import {
  User,
  Smartphone,
  AlertCircle,
  ArrowRight,
  Briefcase,
  HelpCircle,
  Building,
  Sparkles,
  CheckCircle,
  ArrowLeft,
  Lock,
  Eye,
  EyeOff
} from 'lucide-react';

interface LoginScreenProps {
  onLoginSuccess: (
    email: string,
    phone: string,
    name: string,
    role: UserRole,
    password?: string,
    isRegistration?: boolean,
    dashboardNumber?: string
  ) => AuthUser | Promise<AuthUser>;
  onOnboardUser: (userId: string, role: UserRole, name: string, phone: string, city?: string, category?: ServiceCategory) => void;
  currentUser: AuthUser | null;
  onLogout: () => void;
  expectedRole?: UserRole;
}

export default function LoginScreen({
  onLoginSuccess,
  onOnboardUser,
  currentUser,
  onLogout,
  expectedRole = 'customer'
}: LoginScreenProps) {
  const { t } = useTranslation();
  const isAdminRole = expectedRole === 'operator' || expectedRole === 'regional_admin' || expectedRole === 'super_admin';

  // 2-step onboarding state: 'role_selection' -> 'auth'
  const [step, setStep] = useState<'role_selection' | 'auth'>(
    isAdminRole ? 'auth' : 'role_selection'
  );
  const [selectedRole, setSelectedRole] = useState<'customer' | 'specialist' | null>(
    expectedRole === 'specialist' || expectedRole === 'customer'
      ? expectedRole
      : (isAdminRole ? expectedRole as any : null)
  );
  const [pendingUser, setPendingUser] = useState<AuthUser | null>(currentUser);

  const [authMode, setAuthMode] = useState<'register' | 'login'>('register');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [adminUsername, setAdminUsername] = useState('');
  const [adminDashboardNumber, setAdminDashboardNumber] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Sync expectedRole changes
  useEffect(() => {
    if (isAdminRole) {
      setSelectedRole(expectedRole as any);
      setStep('auth');
    }
  }, [expectedRole, isAdminRole]);

  // If currentUser changes and needs onboarding, make sure role is correct
  useEffect(() => {
    if (currentUser && currentUser.isNewUser) {
      setPendingUser(currentUser);
      setSelectedRole(currentUser.role as 'customer' | 'specialist');
      setStep('auth');
    }
  }, [currentUser]);

  const handleAdminLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!adminUsername.trim() || !password.trim()) {
      setErrorMsg('Please enter both username and password.');
      return;
    }
    setErrorMsg(null);
    setIsLoading(true);
    try {
      const user = await onLoginSuccess(adminUsername.trim(), '', adminUsername.trim(), expectedRole, password, false, adminDashboardNumber.trim());
      setPendingUser(user);
      if (user.isNewUser) {
        onOnboardUser(user.id, expectedRole, user.name, user.phone || '');
      }
    } catch (err: any) {
      setErrorMsg(err.message || 'Login failed. Please check your credentials!');
    } finally {
      setIsLoading(false);
    }
  };

  const checkPasswordValidation = (pwd: string) => {
    const isMinLength = pwd.length >= 8;
    const hasLetters = /[a-zA-Zа-яА-Я]/.test(pwd);
    const hasNumbers = /[0-9]/.test(pwd);
    return { isMinLength, hasLetters, hasNumbers, isValid: isMinLength && hasLetters && hasNumbers };
  };

  const handlePhoneSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);

    const phoneVal = validatePhone(phone);
    if (!phoneVal.isValid) {
      setErrorMsg(phoneVal.message || 'Please enter a valid contact phone number.');
      return;
    }

    if (authMode === 'register') {
      if (!name.trim()) {
        setErrorMsg('Please enter your name or company name.');
        return;
      }
      if (!password) {
        setErrorMsg('Please enter a password.');
        return;
      }
      const { isMinLength, hasLetters, hasNumbers } = checkPasswordValidation(password);
      if (!isMinLength) {
        setErrorMsg('Password must be at least 8 characters long.');
        return;
      }
      if (!hasLetters || !hasNumbers) {
        setErrorMsg('Password must contain both letters and numbers.');
        return;
      }
      if (password !== confirmPassword) {
        setErrorMsg('Passwords do not match. Please re-enter confirm password.');
        return;
      }
    } else {
      if (!password) {
        setErrorMsg('Please enter your password.');
        return;
      }
    }

    setIsLoading(true);
    try {
      const cleanPhone = phone.trim().replace(/[^0-9+]/g, '');
      const autoEmail = `${cleanPhone || Date.now()}@nordbase.pt`;
      const roleToUse = selectedRole || 'customer';

      const user = await onLoginSuccess(
        autoEmail,
        phone.trim(),
        name.trim(),
        roleToUse,
        password,
        authMode === 'register'
      );
      setPendingUser(user);

      if (user.isNewUser) {
        onOnboardUser(user.id, roleToUse, user.name || name.trim(), user.phone || phone.trim());
      }
    } catch (err: any) {
      setErrorMsg(err.message || 'Authentication failed. Please check your credentials!');
    } finally {
      setIsLoading(false);
    }
  };

  const decodeJwt = (token: string) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(
        window
          .atob(base64)
          .split('')
          .map((c) => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2))
          .join('')
      );
      return JSON.parse(jsonPayload);
    } catch (e) {
      console.error('Error decoding JWT', e);
      return null;
    }
  };

  useEffect(() => {
    if (step !== 'auth') return;
    let isMounted = true;

    const handleCredentialResponse = async (response: any) => {
      setIsLoading(true);
      setErrorMsg(null);
      try {
        const idToken = response.credential;
        const decoded = decodeJwt(idToken);
        if (!decoded || !decoded.email) {
          throw new Error('Failed to retrieve Google account details.');
        }

        const userName = decoded.name || decoded.email.split('@')[0];
        const roleToUse = selectedRole || 'customer';
        const user = await onLoginSuccess(
          decoded.email,
          phone.trim() || '',
          userName,
          roleToUse,
          undefined,
          false,
          (expectedRole === 'operator' || expectedRole === 'regional_admin') ? adminDashboardNumber.trim() : undefined
        );
        setPendingUser(user);

        if (user.isNewUser) {
          onOnboardUser(user.id, roleToUse, user.name, user.phone || '');
        }
      } catch (err: any) {
        setErrorMsg(err.message || 'Google authorization error. Please use phone login instead!');
      } finally {
        setIsLoading(false);
      }
    };

    const defaultClientId = '107108300547-c42s30trn4g93c7qqmajb9amssd36dgh.apps.googleusercontent.com';

    const setupGoogleSignIn = (clientId: string) => {
      if (!isMounted) return;

      const existingScript = document.querySelector('script[src="https://accounts.google.com/gsi/client"]');

      const initializeGSI = () => {
        const google = (window as any).google;
        if (google && isMounted) {
          google.accounts.id.initialize({
            client_id: clientId,
            callback: handleCredentialResponse,
            auto_select: false,
          });

          const container = document.getElementById('google-signin-container');
          if (container) {
            container.innerHTML = '';
            google.accounts.id.renderButton(container, {
              theme: 'outline',
              size: 'large',
              width: 320,
              text: 'continue_with',
              shape: 'rectangular',
            });
          }
        }
      };

      if (!existingScript) {
        const script = document.createElement('script');
        script.src = 'https://accounts.google.com/gsi/client';
        script.async = true;
        script.defer = true;
        script.onload = initializeGSI;
        document.body.appendChild(script);
      } else {
        const interval = setInterval(() => {
          const google = (window as any).google;
          if (google) {
            clearInterval(interval);
            initializeGSI();
          }
        }, 100);
      }
    };

    fetch('/api/config')
      .then((res) => {
        if (!res.ok) throw new Error('API config returned non-OK status');
        return res.json();
      })
      .then((config) => {
        const clientId = config.googleClientId || defaultClientId;
        setupGoogleSignIn(clientId);
      })
      .catch((err) => {
        console.warn('Failed to load Google configuration from API, using default client ID:', err);
        setupGoogleSignIn(defaultClientId);
      });

    return () => {
      isMounted = false;
    };
  }, [step, onLoginSuccess, phone]);

  const handleSelectRoleAndProceed = (role: 'customer' | 'specialist') => {
    setSelectedRole(role);
    setStep('auth');
  };

  return (
    <div className="w-full max-w-sm mx-auto bg-transparent text-slate-100 animate-in fade-in zoom-in duration-300" id="standard-login-card">
      <div className="p-1 flex flex-col items-center">
        <NordBaseLogo size="md" className="mb-2 sm:mb-4 shrink-0" />

        {errorMsg && (
          <div className="mb-3 w-full p-2.5 sm:p-3 bg-rose-500/10 border border-rose-500/25 rounded-xl text-rose-200 text-xs flex items-center gap-2 animate-shake">
            <AlertCircle className="w-4 h-4 shrink-0 text-rose-400" />
            <span className="font-medium leading-relaxed">{errorMsg}</span>
          </div>
        )}

        {/* STEP 1: ROLE SELECTION */}
        {step === 'role_selection' && (
          <div className="w-full space-y-3 sm:space-y-4 animate-in fade-in duration-300">
            <div className="text-center mb-1">
              <h3 className="text-sm sm:text-base font-display font-black text-white tracking-tight">
                Choose Your Role
              </h3>
              <p className="text-[11px] sm:text-xs text-slate-400 mt-0.5">
                Please select how you would like to sign in
              </p>
            </div>

            <div className="grid grid-cols-1 gap-2.5 sm:gap-3">
              {/* Customer Card */}
              <button
                type="button"
                onClick={() => handleSelectRoleAndProceed('customer')}
                className="group p-3 sm:p-4 rounded-xl sm:rounded-2xl border border-cyan-500/30 bg-gradient-to-r from-cyan-500/5 to-blue-600/5 hover:border-cyan-400/50 hover:from-cyan-500/10 hover:to-blue-600/10 text-left transition-all cursor-pointer flex items-center gap-3"
              >
                <div className="w-9 h-9 sm:w-10 sm:h-10 rounded-xl bg-cyan-500 flex items-center justify-center text-slate-950 shrink-0 shadow-md group-hover:scale-105 transition-transform">
                  <User className="w-4 h-4 sm:w-5 sm:h-5" />
                </div>
                <div className="flex-1 min-w-0">
                  <h4 className="text-xs sm:text-sm font-display font-black text-white group-hover:text-cyan-300 transition-colors">
                    I am a Customer
                  </h4>
                  <p className="text-[10px] sm:text-[11px] text-slate-300 leading-tight mt-0.5">
                    I want to find reliable specialists, post jobs, or request help.
                  </p>
                </div>
              </button>

              {/* Specialist Card */}
              <button
                type="button"
                onClick={() => handleSelectRoleAndProceed('specialist')}
                className="group p-3 sm:p-4 rounded-xl sm:rounded-2xl border border-blue-900/40 bg-slate-950/60 hover:border-cyan-400/50 hover:bg-slate-900/80 text-left transition-all cursor-pointer flex items-center gap-3"
              >
                <div className="w-9 h-9 sm:w-10 sm:h-10 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-center text-cyan-400 shrink-0 group-hover:scale-105 transition-transform">
                  <Briefcase className="w-4 h-4 sm:w-5 sm:h-5" />
                </div>
                <div className="flex-1 min-w-0">
                  <h4 className="text-xs sm:text-sm font-display font-black text-white group-hover:text-cyan-300 transition-colors">
                    I am a Specialist
                  </h4>
                  <p className="text-[10px] sm:text-[11px] text-slate-400 leading-tight mt-0.5">
                    I want to perform jobs, find orders, and receive verified leads.
                  </p>
                </div>
              </button>
            </div>

            <p className="text-[10px] text-slate-500 text-center leading-normal pt-0.5">
              You can always switch your view or configure your profile after signing in.
            </p>
          </div>
        )}

        {/* STEP 2: AUTHENTICATION */}
        {step === 'auth' && (
          <div className="w-full space-y-3 sm:space-y-4">
            {!isAdminRole && (
              <div className="flex items-center justify-between mb-0.5">
                <button
                  type="button"
                  onClick={() => setStep('role_selection')}
                  className="text-xs text-cyan-400 hover:text-cyan-300 font-mono flex items-center gap-1 transition-colors cursor-pointer bg-transparent border-0 p-0"
                >
                  <ArrowLeft className="w-3.5 h-3.5" />
                  <span>{t('auth.changeRole')}</span>
                </button>
                <span className="text-[9px] sm:text-[10px] font-bold uppercase tracking-wider text-slate-400 bg-slate-950/40 px-2 py-0.5 rounded-md border border-blue-950">
                  {selectedRole === 'customer' ? 'Customer' : 'Specialist'}
                </span>
              </div>
            )}

            <div className="text-center mb-0.5">
              <h3 className="text-sm sm:text-base font-display font-bold text-white">
                {isAdminRole 
                  ? 'System Access' 
                  : selectedRole === 'customer' 
                    ? 'Customer Sign In' 
                    : 'Specialist Sign In'}
              </h3>
            </div>

            {isAdminRole ? (
              <form onSubmit={handleAdminLogin} className="w-full space-y-2.5 sm:space-y-3">
                <div>
                  <label className="block text-[11px] sm:text-xs font-bold text-slate-300 mb-1">
                    {t('auth.username', 'Username')}
                  </label>
                  <div className="relative">
                    <span className="absolute inset-y-0 left-0 flex items-center pl-2.5 sm:pl-3 pointer-events-none text-slate-500">
                      <User className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                    </span>
                    <input
                      type="text"
                      required
                      value={adminUsername}
                      onChange={(e) => setAdminUsername(e.target.value)}
                      className="w-full pl-8 sm:pl-9 pr-3 py-2 sm:py-2.5 bg-slate-950/50 border border-blue-900/30 rounded-xl text-xs sm:text-sm text-white focus:outline-none focus:border-cyan-400 focus:ring-1 focus:ring-cyan-400 transition-all placeholder-slate-700 font-medium"
                      placeholder={t('auth.enterUsername', 'Enter username')}
                      disabled={isLoading}
                    />
                  </div>
                </div>

                {(expectedRole === 'operator' || expectedRole === 'regional_admin') && (
                  <div>
                    <label className="block text-[11px] sm:text-xs font-bold text-slate-300 mb-1">
                      Dashboard Number
                    </label>
                    <div className="relative">
                      <span className="absolute inset-y-0 left-0 flex items-center pl-2.5 sm:pl-3 pointer-events-none text-slate-500">
                        <Lock className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                      </span>
                      <input
                        type="text"
                        required
                        value={adminDashboardNumber}
                        onChange={(e) => setAdminDashboardNumber(e.target.value)}
                        className="w-full pl-8 sm:pl-9 pr-3 py-2 sm:py-2.5 bg-slate-950/50 border border-blue-900/30 rounded-xl text-xs sm:text-sm text-white focus:outline-none focus:border-cyan-400 focus:ring-1 focus:ring-cyan-400 transition-all placeholder-slate-700 font-medium"
                        placeholder="e.g. PT-RD-001"
                        disabled={isLoading}
                      />
                    </div>
                  </div>
                )}
                <div>
                  <label className="block text-[11px] sm:text-xs font-bold text-slate-300 mb-1">
                    {t('auth.password', 'Password')}
                  </label>
                  <div className="relative">
                    <span className="absolute inset-y-0 left-0 flex items-center pl-2.5 sm:pl-3 pointer-events-none text-slate-500">
                      <Lock className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                    </span>
                    <input
                      type="password"
                      required
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="w-full pl-8 sm:pl-9 pr-3 py-2 sm:py-2.5 bg-slate-950/50 border border-blue-900/30 rounded-xl text-xs sm:text-sm text-white focus:outline-none focus:border-cyan-400 focus:ring-1 focus:ring-cyan-400 transition-all placeholder-slate-700 font-medium"
                      placeholder={t('auth.enterPassword', 'Enter password')}
                      disabled={isLoading}
                    />
                  </div>
                </div>

                <button
                  type="submit"
                  disabled={isLoading}
                  className="w-full mt-1.5 flex items-center justify-center gap-2 py-2.5 sm:py-3 px-4 bg-gradient-to-r from-blue-600 to-cyan-500 hover:from-blue-500 hover:to-cyan-400 active:scale-95 text-white font-bold rounded-xl text-xs sm:text-sm transition-all shadow-[0_0_12px_rgba(37,99,235,0.3)] disabled:opacity-70 disabled:active:scale-100 cursor-pointer"
                >
                  {isLoading ? (
                    <span className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin"></span>
                  ) : (
                    <span>{t('auth.accessWorkspace')}</span>
                  )}
                  <ArrowRight className="w-4 h-4" />
                </button>
              </form>
            ) : (
              <>
                {/* Google OAuth Button */}
                <div className="w-full flex justify-center py-0.5" id="google-signin-wrapper">
                  <div id="google-signin-container" className="w-full max-w-[280px] sm:max-w-[320px] min-h-[40px] flex justify-center items-center overflow-hidden"></div>
                </div>

                <div className="relative flex py-0.5 items-center">
                  <div className="flex-grow border-t border-blue-950/60"></div>
                  <span className="flex-shrink mx-2 text-[9px] sm:text-[10px] font-bold uppercase tracking-wider text-slate-500">
                    {t('auth.orPhone', 'OR CONTINUE WITH PHONE')}
                  </span>
                  <div className="flex-grow border-t border-blue-950/60"></div>
                </div>

                {/* Registration vs Sign-In Mode Switcher */}
                <div className="flex bg-slate-950/80 p-0.5 sm:p-1 rounded-xl border border-blue-900/40 mb-2">
                  <button
                    type="button"
                    onClick={() => { setAuthMode('register'); setErrorMsg(null); }}
                    className={`flex-1 py-1.5 sm:py-2 text-[11px] sm:text-xs font-bold rounded-lg transition-all ${
                      authMode === 'register'
                        ? 'bg-cyan-500 text-slate-950 shadow-md shadow-cyan-500/20 font-black'
                        : 'text-slate-400 hover:text-white'
                    }`}
                  >
                    {t('auth.createAccount', 'Create Account')}
                  </button>
                  <button
                    type="button"
                    onClick={() => { setAuthMode('login'); setErrorMsg(null); }}
                    className={`flex-1 py-1.5 sm:py-2 text-[11px] sm:text-xs font-bold rounded-lg transition-all ${
                      authMode === 'login'
                        ? 'bg-cyan-500 text-slate-950 shadow-md shadow-cyan-500/20 font-black'
                        : 'text-slate-400 hover:text-white'
                    }`}
                  >
                    {t('auth.signIn', 'Sign In')}
                  </button>
                </div>

                {/* Input Form */}
                <form onSubmit={handlePhoneSubmit} className="w-full space-y-2.5 sm:space-y-3">
                  {authMode === 'register' && (
                    <div>
                      <label className="block text-[11px] sm:text-xs font-bold text-slate-300 mb-1">
                        {t('auth.nameOrg', 'Name / Organization')}
                      </label>
                      <div className="relative">
                        <span className="absolute inset-y-0 left-0 flex items-center pl-2.5 sm:pl-3 pointer-events-none text-slate-500">
                          <Building className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                        </span>
                        <input
                          type="text"
                          required
                          value={name}
                          onChange={(e) => setName(e.target.value)}
                          placeholder={t('auth.nameOrgPlaceholder', 'e.g. Resort Hotel Ltd or John')}
                          className="w-full bg-slate-950/40 border border-blue-900/30 rounded-xl pl-8 sm:pl-9 pr-3 py-2 sm:py-2.5 text-xs sm:text-sm text-white placeholder-slate-600 focus:outline-none focus:border-cyan-400 focus:ring-1 focus:ring-cyan-400 transition-all font-medium"
                        />
                      </div>
                    </div>
                  )}

                  <div>
                    <label className="block text-[11px] sm:text-xs font-bold text-slate-300 mb-1">
                      {t('auth.phoneNumber', 'Phone Number')}
                    </label>
                    <div className="relative">
                      <span className="absolute inset-y-0 left-0 flex items-center pl-2.5 sm:pl-3 pointer-events-none text-slate-500">
                        <Smartphone className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                      </span>
                      <input
                        type="tel"
                        required
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                        placeholder={t('auth.phonePlaceholder', 'e.g. +351 912 345 678')}
                        className="w-full bg-slate-950/40 border border-blue-900/30 rounded-xl pl-8 sm:pl-9 pr-3 py-2 sm:py-2.5 text-xs sm:text-sm text-white placeholder-slate-600 focus:outline-none focus:border-cyan-400 focus:ring-1 focus:ring-cyan-400 transition-all font-mono font-medium"
                      />
                    </div>
                  </div>

                  {/* Password Field */}
                  <div>
                    <label className="block text-[11px] sm:text-xs font-bold text-slate-300 mb-1">
                      {authMode === 'register' ? t('auth.createPassword', 'Create Password') : t('auth.password', 'Password')}
                    </label>
                    <div className="relative">
                      <span className="absolute inset-y-0 left-0 flex items-center pl-2.5 sm:pl-3 pointer-events-none text-slate-500">
                        <Lock className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                      </span>
                      <input
                        type={showPassword ? 'text' : 'password'}
                        required
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder={authMode === 'register' ? t('auth.min8Chars', 'Min. 8 chars, letters & numbers') : t('auth.enterPassword', 'Enter your password')}
                        className="w-full bg-slate-950/40 border border-blue-900/30 rounded-xl pl-8 sm:pl-9 pr-9 py-2 sm:py-2.5 text-xs sm:text-sm text-white placeholder-slate-600 focus:outline-none focus:border-cyan-400 focus:ring-1 focus:ring-cyan-400 transition-all font-medium"
                      />
                      <button
                        type="button"
                        onClick={() => setShowPassword(!showPassword)}
                        className="absolute inset-y-0 right-0 pr-2.5 sm:pr-3 flex items-center text-slate-400 hover:text-cyan-400 transition-colors cursor-pointer"
                        title={showPassword ? t('auth.hidePassword', 'Hide password') : t('auth.showPassword', 'Show password')}
                      >
                        {showPassword ? <EyeOff className="w-3.5 h-3.5 sm:w-4 sm:h-4" /> : <Eye className="w-3.5 h-3.5 sm:w-4 sm:h-4" />}
                      </button>
                    </div>
                  </div>

                  {/* Confirm Password Field (Registration only) */}
                  {authMode === 'register' && (
                    <div>
                      <label className="block text-[11px] sm:text-xs font-bold text-slate-300 mb-1">
                        {t('auth.confirmPassword', 'Confirm Password')}
                      </label>
                      <div className="relative">
                        <span className="absolute inset-y-0 left-0 flex items-center pl-2.5 sm:pl-3 pointer-events-none text-slate-500">
                          <Lock className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                        </span>
                        <input
                          type={showConfirmPassword ? 'text' : 'password'}
                          required
                          value={confirmPassword}
                          onChange={(e) => setConfirmPassword(e.target.value)}
                          placeholder={t('auth.reEnterPassword', 'Re-enter your password')}
                          className="w-full bg-slate-950/40 border border-blue-900/30 rounded-xl pl-8 sm:pl-9 pr-9 py-2 sm:py-2.5 text-xs sm:text-sm text-white placeholder-slate-600 focus:outline-none focus:border-cyan-400 focus:ring-1 focus:ring-cyan-400 transition-all font-medium"
                        />
                        <button
                          type="button"
                          onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                          className="absolute inset-y-0 right-0 pr-2.5 sm:pr-3 flex items-center text-slate-400 hover:text-cyan-400 transition-colors cursor-pointer"
                          title={showConfirmPassword ? t('auth.hidePassword', 'Hide password') : t('auth.showPassword', 'Show password')}
                        >
                          {showConfirmPassword ? <EyeOff className="w-3.5 h-3.5 sm:w-4 sm:h-4" /> : <Eye className="w-3.5 h-3.5 sm:w-4 sm:h-4" />}
                        </button>
                      </div>
                    </div>
                  )}

                  {/* Password Rules Indicators */}
                  {authMode === 'register' && password.length > 0 && (
                    <div className="p-2 sm:p-2.5 bg-slate-950/60 rounded-xl border border-blue-900/30 text-[10px] sm:text-[11px] space-y-0.5 sm:space-y-1 text-slate-300">
                      <div className="font-semibold text-slate-400 mb-0.5">{t('auth.passwordReqs')}</div>
                      <div className={`flex items-center gap-1.5 ${password.length >= 8 ? 'text-emerald-400' : 'text-slate-400'}`}>
                        <span>{password.length >= 8 ? '✓' : '•'}</span>
                        <span>{t('auth.minChars')}</span>
                      </div>
                      <div className={`flex items-center gap-1.5 ${(/[a-zA-Zа-яА-Я]/.test(password) && /[0-9]/.test(password)) ? 'text-emerald-400' : 'text-slate-400'}`}>
                        <span>{(/[a-zA-Zа-яА-Я]/.test(password) && /[0-9]/.test(password)) ? '✓' : '•'}</span>
                        <span>{t('auth.lettersAndNumbers')}</span>
                      </div>
                      {confirmPassword.length > 0 && (
                        <div className={`flex items-center gap-1.5 ${password === confirmPassword ? 'text-emerald-400' : 'text-rose-400'}`}>
                          <span>{password === confirmPassword ? '✓' : '✗'}</span>
                          <span>{password === confirmPassword ? 'Passwords match' : 'Passwords do not match'}</span>
                        </div>
                      )}
                    </div>
                  )}

                  <button
                    type="submit"
                    disabled={isLoading}
                    className="w-full bg-cyan-500 hover:bg-cyan-400 disabled:bg-cyan-800 text-slate-950 font-black uppercase tracking-wider py-2.5 sm:py-3 rounded-xl text-xs sm:text-sm transition-all shadow-[0_0_20px_rgba(6,182,212,0.15)] active:scale-[0.98] cursor-pointer flex items-center justify-center gap-2 mt-1"
                  >
                    {isLoading ? 'Processing...' : (authMode === 'register' ? 'Create Account' : 'Sign In')}
                    <ArrowRight className="w-4 h-4 text-slate-950" />
                  </button>
                </form>

                <p className="text-[9px] sm:text-[10px] text-slate-500 mt-1.5 text-center leading-tight">
                  By continuing, you agree to the Terms of Service. Secure authentication with phone & password.
                </p>
              </>
            )}
          </div>
        )}

      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { AuthUser, SpecialistService, SpecialistAvailabilitySlot } from '../types';
import { Clock, Plus, Trash, Check, X, Calendar, Edit3 } from 'lucide-react';
import { store } from '../store';

interface MarketplaceServicesManagerProps {
  currentUser: AuthUser;
  onUpdateUser: (updatedUser: AuthUser) => void;
}

const DAYS_OF_WEEK = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'] as const;

export default function MarketplaceServicesManager({ currentUser, onUpdateUser }: MarketplaceServicesManagerProps) {
  const [services, setServices] = useState<SpecialistService[]>(currentUser.marketplaceServices || []);
  const [availability, setAvailability] = useState<SpecialistAvailabilitySlot[]>(currentUser.marketplaceAvailability || []);
  const [aboutMe, setAboutMe] = useState(currentUser.aboutMe || currentUser.skillsDescription || '');

  const [isSaving, setIsSaving] = useState(false);
  const [saveMessage, setSaveMessage] = useState('');

  const handleSave = () => {
    setIsSaving(true);
    setSaveMessage('');

    setTimeout(() => {
      const updated = {
        ...currentUser,
        marketplaceServices: services,
        marketplaceAvailability: availability,
        aboutMe: aboutMe
      };

      onUpdateUser(updated);

      setIsSaving(false);
      setSaveMessage('Saved successfully!');
      setTimeout(() => setSaveMessage(''), 3000);
    }, 800);
  };

  const addService = () => {
    setServices([
      ...services, 
      { id: Date.now().toString(), name: '', price: 0, durationMinutes: 60 }
    ]);
  };

  const updateService = (id: string, field: keyof SpecialistService, value: any) => {
    setServices(services.map(s => s.id === id ? { ...s, [field]: value } : s));
  };

  const removeService = (id: string) => {
    setServices(services.filter(s => s.id !== id));
  };

  const addAvailability = () => {
    setAvailability([
      ...availability,
      { dayOfWeek: 'Monday', startTime: '09:00', endTime: '17:00' }
    ]);
  };

  const updateAvailability = (index: number, field: keyof SpecialistAvailabilitySlot, value: any) => {
    const newAvail = [...availability];
    newAvail[index] = { ...newAvail[index], [field]: value };
    setAvailability(newAvail);
  };

  const removeAvailability = (index: number) => {
    const newAvail = [...availability];
    newAvail.splice(index, 1);
    setAvailability(newAvail);
  };

  return (
    <div className="bg-[#0A1128]/95 p-8 rounded-3xl border border-blue-900/30 shadow-lg max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-3 duration-300 text-left">
      <div className="flex justify-between items-center mb-8">
        <div>
          <span className="text-3xl block mb-2">📋</span>
          <h3 className="text-2xl font-display font-black text-white">Services & Schedule</h3>
          <p className="text-slate-400 mt-1">Manage your public marketplace offerings and availability.</p>
        </div>
        <div>
          <button
            onClick={handleSave}
            disabled={isSaving}
            className="bg-cyan-600 hover:bg-cyan-500 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 transition-colors disabled:opacity-50"
          >
            {isSaving ? <Clock className="w-5 h-5 animate-spin" /> : <Check className="w-5 h-5" />}
            {isSaving ? 'Saving...' : 'Save Changes'}
          </button>
          {saveMessage && (
            <div className="text-emerald-400 text-sm font-bold text-right mt-2">{saveMessage}</div>
          )}
        </div>
      </div>

      <div className="space-y-12">
        {/* About Me Section */}
        <section className="bg-slate-900/50 p-6 rounded-2xl border border-slate-800">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-lg font-bold text-white flex items-center gap-2">
              <Edit3 className="w-5 h-5 text-cyan-400" /> Public Description
            </h4>
          </div>
          <textarea
            value={aboutMe}
            onChange={(e) => setAboutMe(e.target.value)}
            placeholder="Tell clients about your experience, approach, and why they should choose you..."
            className="w-full bg-slate-950 border border-slate-700 rounded-xl p-4 text-white focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 min-h-[120px]"
          />
        </section>

        {/* Services Section */}
        <section className="bg-slate-900/50 p-6 rounded-2xl border border-slate-800">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-lg font-bold text-white flex items-center gap-2">
              <Clock className="w-5 h-5 text-cyan-400" /> My Services
            </h4>
            <button onClick={addService} className="text-sm bg-blue-600/20 text-blue-400 hover:bg-blue-600/40 px-3 py-1.5 rounded-lg flex items-center gap-1 transition-colors">
              <Plus className="w-4 h-4" /> Add Service
            </button>
          </div>

          {services.length === 0 ? (
            <p className="text-slate-500 text-sm italic">No services added yet. Add at least one to be bookable.</p>
          ) : (
            <div className="space-y-4">
              {services.map((srv, idx) => (
                <div key={srv.id} className="flex flex-col sm:flex-row gap-4 items-start sm:items-center bg-slate-800/30 p-4 rounded-xl border border-slate-700/50">
                  <div className="flex-1">
                    <label className="block text-xs text-slate-400 mb-1">Service Name</label>
                    <input 
                      type="text" 
                      value={srv.name}
                      onChange={(e) => updateService(srv.id, 'name', e.target.value)}
                      placeholder="e.g. Deep Cleaning, Guitar Lesson"
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm"
                    />
                  </div>
                  <div className="w-24">
                    <label className="block text-xs text-slate-400 mb-1">Price (€)</label>
                    <input 
                      type="number" 
                      value={srv.price}
                      onChange={(e) => updateService(srv.id, 'price', Number(e.target.value))}
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm"
                    />
                  </div>
                  <div className="w-32">
                    <label className="block text-xs text-slate-400 mb-1">Duration (mins)</label>
                    <select
                      value={srv.durationMinutes}
                      onChange={(e) => updateService(srv.id, 'durationMinutes', Number(e.target.value))}
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm"
                    >
                      <option value={30}>30 mins</option>
                      <option value={45}>45 mins</option>
                      <option value={60}>1 hour</option>
                      <option value={90}>1.5 hours</option>
                      <option value={120}>2 hours</option>
                      <option value={180}>3 hours</option>
                      <option value={240}>4 hours</option>
                    </select>
                  </div>
                  <button 
                    onClick={() => removeService(srv.id)}
                    className="mt-5 p-2 text-red-400 hover:bg-red-400/10 rounded-lg transition-colors"
                    title="Remove Service"
                  >
                    <Trash className="w-5 h-5" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </section>

        {/* Availability Section */}
        <section className="bg-slate-900/50 p-6 rounded-2xl border border-slate-800">
          <div className="flex items-center justify-between mb-4">
            <h4 className="text-lg font-bold text-white flex items-center gap-2">
              <Calendar className="w-5 h-5 text-cyan-400" /> Weekly Schedule
            </h4>
            <button onClick={addAvailability} className="text-sm bg-emerald-600/20 text-emerald-400 hover:bg-emerald-600/40 px-3 py-1.5 rounded-lg flex items-center gap-1 transition-colors">
              <Plus className="w-4 h-4" /> Add Slot
            </button>
          </div>

          {availability.length === 0 ? (
            <p className="text-slate-500 text-sm italic">No schedule set. Add your available hours.</p>
          ) : (
            <div className="space-y-3">
              {availability.map((slot, idx) => (
                <div key={idx} className="flex gap-4 items-center bg-slate-800/30 p-3 rounded-xl border border-slate-700/50">
                  <div className="flex-1">
                    <select
                      value={slot.dayOfWeek}
                      onChange={(e) => updateAvailability(idx, 'dayOfWeek', e.target.value)}
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm"
                    >
                      {DAYS_OF_WEEK.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                  </div>
                  <div className="flex items-center gap-2">
                    <input 
                      type="time" 
                      value={slot.startTime}
                      onChange={(e) => updateAvailability(idx, 'startTime', e.target.value)}
                      className="bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm"
                    />
                    <span className="text-slate-500">to</span>
                    <input 
                      type="time" 
                      value={slot.endTime}
                      onChange={(e) => updateAvailability(idx, 'endTime', e.target.value)}
                      className="bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm"
                    />
                  </div>
                  <button 
                    onClick={() => removeAvailability(idx)}
                    className="p-2 text-red-400 hover:bg-red-400/10 rounded-lg transition-colors"
                  >
                    <Trash className="w-4 h-4" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { AuthUser, SubscriptionPlan } from '../types';
import { Check, Star, Shield, Zap } from 'lucide-react';

interface MarketplaceSubscriptionProps {
  currentUser: AuthUser;
  onActivate: (plan: SubscriptionPlan) => void;
}

export default function MarketplaceSubscription({ currentUser, onActivate }: MarketplaceSubscriptionProps) {
  const [selectedPlan, setSelectedPlan] = useState<SubscriptionPlan | null>('1_month_free');
  const [showPayment, setShowPayment] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const plans = [
    { id: '1_month_free', name: '1 Month Trial', price: '€0', duration: 'First month', highlight: true },
    { id: '1_month', name: '1 Month', price: '€10', duration: 'per month' },
    { id: '3_months', name: '3 Months', price: '€25', duration: 'quarterly', savings: 'Save €5' },
    { id: '6_months', name: '6 Months', price: '€45', duration: 'biannually', savings: 'Save €15' },
    { id: '12_months', name: '12 Months', price: '€80', duration: 'annually', savings: 'Save €40' }
  ];

  const handleActivate = () => {
    if (selectedPlan === '1_month_free') {
      setIsProcessing(true);
      setTimeout(() => {
        onActivate('1_month_free');
      }, 1500);
    } else {
      setShowPayment(true);
    }
  };

  const handleMBWayPayment = () => {
    setIsProcessing(true);
    setTimeout(() => {
      onActivate(selectedPlan as SubscriptionPlan);
    }, 2000);
  };

  if (showPayment) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-slate-100 p-6">
        <div className="max-w-md w-full bg-slate-900 border border-slate-800 rounded-3xl p-8 shadow-2xl text-center space-y-6">
          <div className="w-20 h-20 bg-blue-600/20 rounded-full flex items-center justify-center mx-auto mb-4">
            <Zap className="w-10 h-10 text-blue-400" />
          </div>
          <h2 className="text-3xl font-bold text-white">Complete Payment</h2>
          <p className="text-slate-400 text-lg">
            You selected the {plans.find(p => p.id === selectedPlan)?.name} plan for {plans.find(p => p.id === selectedPlan)?.price}.
          </p>

          <div className="pt-6">
            <button
              onClick={handleMBWayPayment}
              disabled={isProcessing}
              className="w-full bg-[#00A859] hover:bg-[#00924E] text-white font-bold py-4 rounded-xl text-lg transition-all shadow-lg flex items-center justify-center gap-3 disabled:opacity-50"
            >
              {isProcessing ? 'Processing Payment...' : 'Pay with MB Way'}
            </button>
          </div>
          <button onClick={() => setShowPayment(false)} className="text-slate-500 hover:text-slate-300 mt-4 underline text-sm transition-colors">
            Go back to plans
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col items-center justify-center min-h-screen text-slate-100 py-12 px-4 sm:px-6">
      <div className="max-w-3xl w-full space-y-12">
        <div className="text-center space-y-4">
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-cyan-500/10 text-cyan-400 text-sm font-semibold border border-cyan-500/20 mb-4">
            <Star className="w-4 h-4" /> Welcome to NordBase Marketplace
          </div>
          <h1 className="text-4xl sm:text-5xl font-extrabold text-white tracking-tight">Activate Your Profile</h1>
          <p className="text-xl text-slate-400 max-w-2xl mx-auto leading-relaxed">
            Congratulations on completing your profile! As a special welcome gift, enjoy your first month completely <strong className="text-cyan-400">free</strong>.
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {plans.map(plan => (
            <div 
              key={plan.id}
              onClick={() => setSelectedPlan(plan.id as SubscriptionPlan)}
              className={`relative cursor-pointer transition-all duration-300 rounded-3xl p-6 border-2 ${
                selectedPlan === plan.id 
                  ? 'border-cyan-500 bg-cyan-950/20 shadow-[0_0_30px_-5px_rgba(6,182,212,0.3)]' 
                  : 'border-slate-800 bg-slate-900/50 hover:border-slate-700 hover:bg-slate-800/50'
              } ${plan.highlight ? 'md:col-span-2 bg-gradient-to-br from-cyan-950/40 to-slate-900' : ''}`}
            >
              {plan.highlight && selectedPlan !== plan.id && (
                <div className="absolute -top-3 -right-3 bg-cyan-500 text-white text-xs font-bold px-3 py-1 rounded-full shadow-lg">
                  Recommended
                </div>
              )}
              {selectedPlan === plan.id && (
                <div className="absolute top-4 right-4 text-cyan-400">
                  <Check className="w-6 h-6" />
                </div>
              )}

              <div className="flex flex-col h-full justify-between">
                <div>
                  <h3 className={`text-2xl font-bold ${plan.highlight ? 'text-cyan-300' : 'text-slate-200'}`}>{plan.name}</h3>
                  <div className="mt-2 flex items-baseline gap-2">
                    <span className="text-4xl font-extrabold text-white">{plan.price}</span>
                    <span className="text-slate-500 font-medium">{plan.duration}</span>
                  </div>
                  {plan.savings && (
                    <div className="mt-2 text-sm font-semibold text-emerald-400 bg-emerald-400/10 inline-block px-2 py-1 rounded">
                      {plan.savings}
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 text-sm text-slate-400 flex gap-4 items-start">
          <Shield className="w-6 h-6 text-slate-500 shrink-0 mt-0.5" />
          <p>
            By subscribing, your profile will be publicly visible to clients in the marketplace. You will receive direct booking requests for your personalized services. Your subscription automatically renews, and you can cancel anytime.
          </p>
        </div>

        <div className="text-center pb-12">
          <button
            onClick={handleActivate}
            disabled={!selectedPlan || isProcessing}
            className="w-full sm:w-auto min-w-[280px] bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-lg px-8 py-5 rounded-2xl transition-all shadow-[0_0_20px_-5px_rgba(6,182,212,0.4)] hover:shadow-[0_0_25px_-5px_rgba(6,182,212,0.6)] hover:-translate-y-1 disabled:opacity-50 disabled:hover:translate-y-0"
          >
            {isProcessing ? 'Processing...' : (selectedPlan === '1_month_free' ? 'Start Free Trial' : 'Continue to Payment')}
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { AuthUser, ServiceCategory } from '../types';
import { Search, MapPin, Star, Shield, Filter, ChevronLeft, Phone, Languages, Mail, MessageCircle, Calendar } from 'lucide-react';
import { store } from '../store';
import { AddressAutocomplete } from './AddressAutocomplete';

interface MarketplaceViewProps {
  category: ServiceCategory;
  specialty?: string;
  onGoBack: () => void;
  currentUser: AuthUser | null;
  onSubmitDirectRequest: (specialistId: string, description: string) => void;
}

export default function MarketplaceView({ category, specialty, onGoBack, currentUser, onSubmitDirectRequest }: MarketplaceViewProps) {
  const [searchQuery, setSearchQuery] = useState(specialty || '');
  const [selectedCity, setSelectedCity] = useState('');
  const [selectedSpecialist, setSelectedSpecialist] = useState<AuthUser | null>(null);
  const [requestText, setRequestText] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // We fetch directly from store for simplicity in this component,
  // or we could get it passed down. 
  const allSpecialists = store.getState().users.filter(u => u.role === 'specialist' && u.categories?.some((c: any) => ['Care', 'Lessons', 'Business'].includes(c.name || c)));

  const specialists = useMemo(() => {
    return allSpecialists.filter(s => {
      // Must match the main category (Care, Lessons, Other)
      const hasCategory = s.categories?.some(c => {
        const cName = typeof c === 'string' ? c : (c as any).name;
        return cName === category;
      });
      if (!hasCategory) return false;

      // Filter by search query
      if (searchQuery) {
        const q = searchQuery.toLowerCase();
        const matchesName = s.name.toLowerCase().includes(q);
        const matchesAbout = s.aboutMe?.toLowerCase().includes(q) || s.skillsDescription?.toLowerCase().includes(q) || s.specialtiesWithLevels?.some(sp => sp.specialty.toLowerCase().includes(q));
        const matchesServices = s.marketplaceServices?.some(srv => srv.name.toLowerCase().includes(q));
        if (!matchesName && !matchesAbout && !matchesServices) return false;
      }

      // Filter by city (locationSearch)
      if (selectedCity) {
        const loc = selectedCity.toLowerCase();
        const sCity = (s.city || '').toLowerCase();
        if (!loc.includes(sCity) && !sCity.includes(loc)) {
          return false;
        }
      }

      return true;
    });
  }, [allSpecialists, category, searchQuery, selectedCity]);

  // Extract unique cities for the filter


  const handleDirectRequest = () => {
    if (!requestText.trim() || !selectedSpecialist) return;
    setIsSubmitting(true);
    setTimeout(() => {
      onSubmitDirectRequest(selectedSpecialist.id, requestText);
      setIsSubmitting(false);
      setSelectedSpecialist(null);
      setRequestText('');
    }, 1000);
  };

  if (selectedSpecialist) {
    return (
      <div className="max-w-4xl mx-auto px-4 py-8">
        <button 
          onClick={() => setSelectedSpecialist(null)}
          className="flex items-center gap-2 text-cyan-400 hover:text-cyan-300 font-medium mb-6 transition-colors"
        >
          <ChevronLeft className="w-5 h-5" /> Back to specialists
        </button>

        <div className="bg-slate-900 border border-slate-800 rounded-3xl overflow-hidden shadow-2xl">
          <div className="h-32 bg-gradient-to-r from-cyan-950 to-blue-900 relative"></div>
          <div className="px-8 pb-8 relative">
            <div className="flex flex-col sm:flex-row gap-6 items-start sm:items-end -mt-16 mb-6">
              <div className="w-32 h-32 rounded-full border-4 border-slate-900 bg-slate-800 flex items-center justify-center overflow-hidden flex-shrink-0 z-10 shadow-xl">
                {selectedSpecialist.photoUrl ? (
                  <img src={selectedSpecialist.photoUrl} alt={selectedSpecialist.name} className="w-full h-full object-cover" />
                ) : (
                  <span className="text-4xl font-bold text-slate-500">{selectedSpecialist.name.charAt(0)}</span>
                )}
              </div>
              <div className="flex-1 pb-2">
                <h1 className="text-3xl font-extrabold text-white flex items-center gap-2">
                  {selectedSpecialist.name}
                  {selectedSpecialist.verificationDocuments && selectedSpecialist.verificationDocuments.length > 0 && (
                    <Shield className="w-6 h-6 text-emerald-400" />
                  )}
                </h1>
                <p className="text-slate-400 text-lg flex items-center gap-2 mt-1">
                  <MapPin className="w-4 h-4" /> {selectedSpecialist.city || 'Remote'}
                </p>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              <div className="md:col-span-2 space-y-8">
                {/* About Section */}
                <section>
                  <h3 className="text-xl font-bold text-slate-200 mb-3 border-b border-slate-800 pb-2">About Me</h3>
                  <p className="text-slate-300 leading-relaxed whitespace-pre-wrap">
                    {selectedSpecialist.aboutMe || selectedSpecialist.skillsDescription || "No description provided."}
                  </p>
                </section>

                {/* Services Section */}
                {selectedSpecialist.marketplaceServices && selectedSpecialist.marketplaceServices.length > 0 && (
                  <section>
                    <h3 className="text-xl font-bold text-slate-200 mb-3 border-b border-slate-800 pb-2">Services & Pricing</h3>
                    <div className="grid gap-3">
                      {selectedSpecialist.marketplaceServices.map(srv => (
                        <div key={srv.id} className="bg-slate-800/50 p-4 rounded-xl flex justify-between items-center border border-slate-700/50">
                          <div>
                            <h4 className="font-semibold text-white text-lg">{srv.name}</h4>
                            <p className="text-slate-400 text-sm">Duration: {srv.durationMinutes} mins</p>
                          </div>
                          <div className="text-xl font-bold text-cyan-400">
                            €{srv.price}
                          </div>
                        </div>
                      ))}
                    </div>
                  </section>
                )}

                {/* Availability Section */}
                {selectedSpecialist.marketplaceAvailability && selectedSpecialist.marketplaceAvailability.length > 0 && (
                  <section>
                    <h3 className="text-xl font-bold text-slate-200 mb-3 border-b border-slate-800 pb-2">Availability</h3>
                    <div className="flex flex-wrap gap-2">
                      {selectedSpecialist.marketplaceAvailability.map((avail, idx) => (
                        <div key={idx} className="bg-blue-900/20 border border-blue-500/20 text-blue-300 px-3 py-2 rounded-lg text-sm flex items-center gap-2">
                          <Calendar className="w-4 h-4" />
                          <span className="font-medium">{avail.dayOfWeek}</span>
                          <span>{avail.startTime} - {avail.endTime}</span>
                        </div>
                      ))}
                    </div>
                  </section>
                )}
              </div>

              {/* Sidebar Contact / Request */}
              <div className="space-y-6">
                <div className="bg-slate-800/30 border border-slate-700 rounded-2xl p-5">
                  <h3 className="text-lg font-bold text-white mb-4">Request Service</h3>
                  <textarea
                    value={requestText}
                    onChange={(e) => setRequestText(e.target.value)}
                    placeholder="Describe what you need help with..."
                    className="w-full bg-slate-900/50 border border-slate-600 rounded-xl p-3 text-white placeholder-slate-500 focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 min-h-[120px] mb-4"
                  ></textarea>
                  <button
                    onClick={handleDirectRequest}
                    disabled={isSubmitting || !requestText.trim()}
                    className="w-full bg-cyan-600 hover:bg-cyan-500 text-white font-bold py-3 rounded-xl transition-colors shadow-lg shadow-cyan-500/20 disabled:opacity-50 disabled:shadow-none"
                  >
                    {isSubmitting ? 'Sending Request...' : 'Send Request'}
                  </button>
                  {!currentUser && (
                    <p className="text-xs text-slate-500 mt-3 text-center">
                      You will be asked to log in or create an account to track this request.
                    </p>
                  )}
                </div>

                <div className="bg-slate-800/30 border border-slate-700 rounded-2xl p-5 space-y-4">
                  <h3 className="text-lg font-bold text-white">Details</h3>
                  {selectedSpecialist.languages && selectedSpecialist.languages.length > 0 && (
                    <div>
                      <div className="text-slate-400 text-sm mb-1 flex items-center gap-1"><Languages className="w-4 h-4"/> Languages</div>
                      <div className="flex flex-wrap gap-1">
                        {selectedSpecialist.languages.map(lang => (
