                  {/* STEP 8: DECLARATION */}
                  {currentStep === 8 && (
                    <div className="space-y-6">
                      <div className="border-b border-slate-800 pb-4">
                        <h2 className="text-xl font-bold text-white flex items-center space-x-2">
