import { store } from '../../store';
import { Specialist, Job } from '../../types';
import { SimulationStep, TestScenario } from './types';

export class AdvancedPack2Agent {
  public static packTitle = 'Package 2: Advanced Business & Edge-Case Scenarios';

  public static async runAllPack2Scenarios(): Promise<TestScenario[]> {
    const s1 = await AdvancedPack2Agent.runDisputeAndRefundScenario();
    const s2 = await AdvancedPack2Agent.runCompetitiveBiddingScenario();
    const s3 = await AdvancedPack2Agent.runTerritoryReRoutingScenario();
    const s4 = await AdvancedPack2Agent.runEscalationAuditScenario();
    const s5 = await AdvancedPack2Agent.runEmergencyReDispatchScenario();
    return [s1, s2, s3, s4, s5];
  }

  /**
   * Scenario 1: Dispute & Lead Fee Refund Workflow
   */
  public static async runDisputeAndRefundScenario(): Promise<TestScenario> {
    const startTime = Date.now();
    const steps: SimulationStep[] = [];
    const logs: string[] = [];

    logs.push('[Pack 2] Initiating Dispute & Lead Fee Refund Workflow...');

    // 1. Create specialist with initial balance €50
    const spec: Specialist = {
      id: `spec_refund_${Date.now()}`,
      name: 'João Silva (HVAC)',
      phone: '+351 922 111 000',
      category: 'Home Services',
      categories: ['Home Services'],
      city: 'Portimão',
      balance: 50,
      unlockedJobs: [],
      status: 'approved'
    };
    store.updateSpecialists([...store.getState().specialists, spec]);

    // 2. Customer creates job and spec unlocks it for €20
    const job = await store.createJobRequest('False Alarm Client', '+351 912 345 678', 'Portimão', 'AC Repair');
    await store.offerJobToSpecialists(job.id, 2, 120, 20, 'Urgent AC repair', [spec.id]);
    await store.selectSpecialistForJob(job.id, spec.id);

    const unlockOk = await store.unlockJob(job.id, spec.id);
    logs.push(`[Pack 2] Spec unlocked lead (€20 fee). Success: ${unlockOk}. Balance before refund: €${store.getState().specialists.find(s => s.id === spec.id)?.balance}`);

    // 3. Customer cancels order due to false call
    store.updateJobs(store.getState().jobs.map(j => j.id === job.id ? { ...j, status: 'cancelled' as const } : j));
    logs.push(`[Pack 2] Order canceled by customer.`);

    // 4. Operator issues lead fee refund
    let specAfterRefund = store.getState().specialists.find(s => s.id === spec.id);
    if (specAfterRefund) {
      // Refund balance
      store.updateSpecialists(
        store.getState().specialists.map(s => s.id === spec.id ? { ...s, balance: s.balance + 20 } : s)
      );
    }
    specAfterRefund = store.getState().specialists.find(s => s.id === spec.id);
    logs.push(`[Pack 2] Lead fee refunded by TP. New balance: €${specAfterRefund?.balance}`);

    const canceledJob = store.getState().jobs.find(j => j.id === job.id);
    const isSuccess = unlockOk && canceledJob?.status === 'cancelled' && specAfterRefund?.balance === 50;

    steps.push({
      id: 'pack2_s1_step1',
      name: 'Execute Lead Fee Refund on Customer Cancellation',
      description: 'Verifies that when a client cancels a false-alarm job, the operator can issue a 100% lead fee refund back to specialist balance',
      agentRole: 'agent_3_tp',
      status: isSuccess ? 'passed' : 'failed',
      durationMs: 45,
      logs,
      assertions: [
        { label: 'Lead unlocked originally with €20 deduction', passed: unlockOk },
        { label: 'Job status transitioned to canceled', passed: canceledJob?.status === 'cancelled' },
        { label: 'Specialist balance fully restored (€50)', passed: specAfterRefund?.balance === 50, details: `€${specAfterRefund?.balance}` }
      ]
    });

    return {
      id: 'scenario_pack2_dispute_refund',
      title: '📦 Pack 2 - Case 1: Dispute Investigation & Lead Fee Refund Engine',
      agentName: 'Advanced Pack 2 Agent',
      agentRole: 'agent_3_tp',
      description: 'Simulates customer cancellation investigation and automated lead fee credit refund back to contractor wallet',
      steps,
      status: isSuccess ? 'passed' : 'failed',
      startedAt: new Date(startTime).toISOString(),
      completedAt: new Date().toISOString(),
      totalDurationMs: Date.now() - startTime
    };
  }

  /**
   * Scenario 2: Multi-Specialist Competitive Bidding & Rating Match
   */
  public static async runCompetitiveBiddingScenario(): Promise<TestScenario> {
    const startTime = Date.now();
    const steps: SimulationStep[] = [];
    const logs: string[] = [];

