    const specs: Specialist[] = [
      { id: `spec_b1_${Date.now()}`, name: 'Master Pro (Rating 4.9)', phone: '+351 900 11', category: 'Home Services', categories: ['Home Services'], city: 'Faro', balance: 150, unlockedJobs: [], status: 'approved' },
      { id: `spec_b2_${Date.now()}`, name: 'Electric Junior (Rating 4.1)', phone: '+351 900 22', category: 'Home Services', categories: ['Home Services'], city: 'Faro', balance: 80, unlockedJobs: [], status: 'approved' },
      { id: `spec_b3_${Date.now()}`, name: 'Volt Expert (Rating 4.8)', phone: '+351 900 33', category: 'Home Services', categories: ['Home Services'], city: 'Faro', balance: 200, unlockedJobs: [], status: 'approved' }
    ];

    store.updateSpecialists([...store.getState().specialists, ...specs]);

    const job = await store.createJobRequest('Commercial Solar Repair', '+351 988 777 666', 'Faro', 'Industrial electrical system');
