        { label: 'Customer emergency response time < 3 mins', passed: true }
      ]
    });

    return {
      id: 'scenario_pack2_emergency',
      title: '📦 Pack 2 - Case 5: Emergency Re-Dispatch & Backup Contractor Failover',
