import { store } from '../../store';
import { AuthUser, Job, Specialist, ServiceCategory } from '../../types';
import { SimulationStep, TestScenario } from './types';

export class BillingVerificationAgent {
  public static agentTitle = 'Financial Engine & Wallet Ledger Audit Agent';

  /**
   * Comprehensive Financial & Billing Verification Suite:
   * 1. Top-Up & Deposit Integrity
   * 2. Lead Purchase Deduction & Exact Ledger Math
   * 3. Overdraft Guard (Insufficient Balance Rejection)
   * 4. Double-Charge Protection
   * 5. Dispute Resolution Lead Fee Refund
   */
  public static async runBillingVerificationSuite(): Promise<TestScenario> {
    const startTime = Date.now();
    const steps: SimulationStep[] = [];
    const logs: string[] = [];

    logs.push('[Financial Engine] Initializing Wallet Ledger & Transaction Integrity Audit...');

    const now = Date.now();

    // ------------------------------------------------------------------
    // TEST 1: Wallet Top-Up & Balance Increment
    // ------------------------------------------------------------------
    const step1Logs: string[] = [];
    step1Logs.push('[Top-Up Test] Initializing test contractor wallet with €0 initial balance...');

    const testSpec: Specialist = {
      id: `spec_fin_${now}`,
      name: 'Manuel Financial Test',
      phone: '+351 930 111 222',
      category: 'Repairs' as ServiceCategory,
      categories: ['Repairs'],
      city: 'Portimão',
      balance: 0,
      unlockedJobs: [],
      status: 'approved',
      skillsDescription: 'HVAC & Plumbing'
    };

    const currentSpecs = store.getState().specialists;
    store.updateSpecialists([...currentSpecs, testSpec]);

    step1Logs.push(`Specialist created: ${testSpec.name} (ID: ${testSpec.id}). Starting Balance: €${testSpec.balance}`);

    // Perform Top-up of €150
    const topupAmount = 150;
    await store.topupSpecialist(testSpec.id, topupAmount);

    const specAfterTopup = store.getState().specialists.find(s => s.id === testSpec.id);
    step1Logs.push(`Top-up of €${topupAmount} executed. New Balance: €${specAfterTopup?.balance}`);

    const topupPassed = specAfterTopup?.balance === 150;

    steps.push({
      id: 'fin_step1_topup',
      name: 'Wallet Test 1: Deposit & Top-up Increment Guard',
      description: 'Validates accurate addition of funds to contractor wallet balance',
      agentRole: 'agent_4_specialist',
      status: topupPassed ? 'passed' : 'failed',
      durationMs: 30,
      logs: step1Logs,
      assertions: [
        { label: 'Initial balance was €0', passed: testSpec.balance === 0 },
        { label: 'Top-up of €150 credited cleanly', passed: topupPassed, details: `€${specAfterTopup?.balance}` }
      ]
    });

    // ------------------------------------------------------------------
    // TEST 2: Lead Purchase Deduction & Exact Ledger Math
    // ------------------------------------------------------------------
    const step2Logs: string[] = [];
    step2Logs.push('[Lead Purchase] Creating active job with €25 lead price...');

    const job1 = await store.createJobRequest('Billing Client 1', '+351 912 333 444', 'Av. Guanabara 4, Portimão', 'AC Repair required');
    const leadPrice1 = 25;
    await store.offerJobToSpecialists(job1.id, 2, 200, leadPrice1, 'AC Repair Lead', [testSpec.id]);
    await store.expressInterest(job1.id, testSpec.id);
    await store.selectSpecialistForJob(job1.id, testSpec.id);

    step2Logs.push(`Pre-purchase balance: €${specAfterTopup?.balance}. Lead Price: €${leadPrice1}`);

    const unlockRes = await store.unlockJob(job1.id, testSpec.id);
    const specAfterPurchase = store.getState().specialists.find(s => s.id === testSpec.id);

    step2Logs.push(`Unlock result: ${unlockRes ? 'SUCCESS' : 'FAILED'}. Post-purchase balance: €${specAfterPurchase?.balance}`);

    const expectedBalance2 = 150 - leadPrice1; // 125
    const deductionPassed = unlockRes && specAfterPurchase?.balance === expectedBalance2;

    steps.push({
      id: 'fin_step2_deduction',
      name: 'Wallet Test 2: Lead Purchase Fee Deduction Integrity',
      description: 'Verifies exact deduction of lead unlock fee (€25) from contractor balance without math drift',
      agentRole: 'agent_4_specialist',
      status: deductionPassed ? 'passed' : 'failed',
      durationMs: 35,
      logs: step2Logs,
      assertions: [
        { label: 'Lead unlocked successfully', passed: unlockRes },
        { label: 'Balance deducted exactly €25 (€150 -> €125)', passed: specAfterPurchase?.balance === expectedBalance2, details: `€${specAfterPurchase?.balance}` }
      ]
    });

    // ------------------------------------------------------------------
    // TEST 3: Overdraft Guard (Insufficient Funds Rejection)
    // ------------------------------------------------------------------
    const step3Logs: string[] = [];
    step3Logs.push('[Overdraft Guard] Testing transaction rejection when wallet balance is insufficient...');

    // Create broke specialist with €10
    const brokeSpec: Specialist = {
      id: `spec_broke_${now}`,
      name: 'Low Balance Contractor',
      phone: '+351 930 999 888',
      category: 'Repairs' as ServiceCategory,
      categories: ['Repairs'],
      city: 'Portimão',
      balance: 10, // Only €10
      unlockedJobs: [],
      status: 'approved',
      skillsDescription: 'General Handyman'
    };
    store.updateSpecialists([...store.getState().specialists, brokeSpec]);

    // Job costing €40
    const job2 = await store.createJobRequest('Billing Client 2', '+351 912 555 666', 'Rua Nova 12, Portimão', 'Full Rewiring');
    const expensiveLeadPrice = 40;
    await store.offerJobToSpecialists(job2.id, 5, 450, expensiveLeadPrice, 'High Value Rewiring', [brokeSpec.id]);
    await store.expressInterest(job2.id, brokeSpec.id);
    await store.selectSpecialistForJob(job2.id, brokeSpec.id);

    step3Logs.push(`Specialist balance: €${brokeSpec.balance}. Lead price: €${expensiveLeadPrice}`);
    step3Logs.push(`Attempting lead unlock with insufficient balance...`);

    const overdraftAttemptRes = await store.unlockJob(job2.id, brokeSpec.id);
    const brokeSpecAfterAttempt = store.getState().specialists.find(s => s.id === brokeSpec.id);
    const job2AfterAttempt = store.getState().jobs.find(j => j.id === job2.id);

    step3Logs.push(`Overdraft Unlock Result: ${overdraftAttemptRes ? 'ALLOWED (DEFECT!)' : 'REJECTED (SAFE!)'}`);
    step3Logs.push(`Post-attempt balance: €${brokeSpecAfterAttempt?.balance}. Job status: ${job2AfterAttempt?.status}`);

    const overdraftPassed = !overdraftAttemptRes && brokeSpecAfterAttempt?.balance === 10 && job2AfterAttempt?.status !== 'active';

    steps.push({
      id: 'fin_step3_overdraft',
      name: 'Wallet Test 3: Insufficient Funds Overdraft Guard',
      description: 'Ensures transactions are blocked when lead fee exceeds available wallet balance',
      agentRole: 'agent_4_specialist',
      status: overdraftPassed ? 'passed' : 'failed',
      durationMs: 30,
      logs: step3Logs,
      assertions: [
        { label: 'Unlock transaction returned false', passed: !overdraftAttemptRes },
        { label: 'Wallet balance preserved (€10 untouched)', passed: brokeSpecAfterAttempt?.balance === 10, details: `€${brokeSpecAfterAttempt?.balance}` },
        { label: 'Job contact details remain protected', passed: job2AfterAttempt?.status !== 'active' }
      ]
    });

    // ------------------------------------------------------------------
    // TEST 4: Double Lead Unlock & Balance Deduct Guard
    // ------------------------------------------------------------------
    const step4Logs: string[] = [];
    step4Logs.push('[Double Charge Guard] Testing duplicate unlock prevention on job #' + job1.id);

    const balanceBeforeDouble = store.getState().specialists.find(s => s.id === testSpec.id)?.balance || 0;
    step4Logs.push(`Balance before 2nd unlock attempt: €${balanceBeforeDouble}`);

    // Attempting unlock on an already active job
    const doubleUnlockRes = await store.unlockJob(job1.id, testSpec.id);
    const balanceAfterDouble = store.getState().specialists.find(s => s.id === testSpec.id)?.balance || 0;

    step4Logs.push(`2nd Unlock result: ${doubleUnlockRes ? 'SUCCESS' : 'BLOCKED'}. Balance: €${balanceAfterDouble}`);

    const doublePassed = !doubleUnlockRes && balanceBeforeDouble === balanceAfterDouble;

    steps.push({
      id: 'fin_step4_double_charge',
      name: 'Wallet Test 4: Double Unlock & Re-Charge Prevention',
      description: 'Prevents multiple lead fee charges for an already unlocked job',
      agentRole: 'agent_4_specialist',
      status: doublePassed ? 'passed' : 'failed',
      durationMs: 25,
      logs: step4Logs,
      assertions: [
        { label: 'Duplicate unlock attempt rejected', passed: !doubleUnlockRes },
        { label: 'Balance remained identical (No double deduction)', passed: balanceBeforeDouble === balanceAfterDouble, details: `€${balanceAfterDouble}` }
      ]
    });

    // ------------------------------------------------------------------
    // TEST 5: Dispute Cancellation Lead Fee Refund
    // ------------------------------------------------------------------
    const step5Logs: string[] = [];
    step5Logs.push('[Refund Test] Issuing €25 lead fee refund due to job cancellation by operator...');

    const balancePreRefund = store.getState().specialists.find(s => s.id === testSpec.id)?.balance || 0;
    step5Logs.push(`Pre-refund balance for ${testSpec.name}: €${balancePreRefund}`);

    // Perform refund of leadPrice1 (€25) on job1
    await store.refundLeadFeeAndCancelJob(job1.id, leadPrice1, testSpec.id, 'Client cancelled order due to flood emergency');

    const specPostRefund = store.getState().specialists.find(s => s.id === testSpec.id);
    const expectedPostRefund = balancePreRefund + leadPrice1; // 125 + 25 = 150

    step5Logs.push(`Refund of €${leadPrice1} processed. Post-refund balance: €${specPostRefund?.balance}`);

    // Check audit logs for refund entry
    const auditLogs = store.getState().auditLogs;
    const hasRefundLog = auditLogs.some(log => log.action === 'Lead Refund Issued' && log.details.includes(`Refunded €${leadPrice1}`));
    step5Logs.push(`Audit log recorded for lead refund: ${hasRefundLog ? 'YES' : 'NO'}`);

    const refundPassed = specPostRefund?.balance === expectedPostRefund && hasRefundLog;

    steps.push({
      id: 'fin_step5_refund',
      name: 'Wallet Test 5: Dispute Resolution Refund & Audit Ledger',
      description: 'Validates automated lead fee reimbursement to contractor balance upon operator cancellation',
      agentRole: 'agent_3_tp',
      status: refundPassed ? 'passed' : 'failed',
      durationMs: 40,
      logs: step5Logs,
      assertions: [
        { label: 'Wallet balance restored by exact lead fee (€25)', passed: specPostRefund?.balance === expectedPostRefund, details: `€${specPostRefund?.balance}` },
        { label: 'Audit log ledger entry generated for financial refund', passed: hasRefundLog }
      ]
    });

    return {
      id: 'scenario_billing_verification_suite',
      title: 'FINANCIAL ENGINE & LEDGER AUDIT SUITE: Deposits • Fee Deductions • Overdraft Guard • Dispute Refunds',
      agentName: 'Financial Engine & Billing Auditor',
      agentRole: 'agent_1_super_admin',
      description: 'Verifies the complete monetary lifecycle of contractor wallets: tests top-up deposits, lead unlock deductions, overdraft rejection guards, double-charge guards, and operator dispute refund ledgers.',
      steps,
      status: steps.every(s => s.status === 'passed') ? 'passed' : 'failed',
      startedAt: new Date(startTime).toISOString(),
      completedAt: new Date().toISOString(),
      totalDurationMs: Date.now() - startTime
    };
  }
}

import { store } from '../../store';
import { AuthUser, Job, Specialist, ServiceCategory } from '../../types';
import { canSendMessage, canViewChat, canViewAttachment } from '../permissions';
import { SimulationStep, TestScenario } from './types';

export class ChatVerificationAgent {
  public static agentTitle = 'Chat Architecture & Multi-Channel Verification Agent';

  /**
   * Comprehensive Chat System Test Suite:
   * 1. Channel Permission Matrix (Security Guard)
   * 2. Multi-Role Back-and-Forth Dialogue & Delivery Integrity
   * 3. Attachment Privacy & Scope Control
   * 4. Operator Dispute Arbitration Chat Injections
   */
  public static async runChatVerificationSuite(): Promise<TestScenario> {
    const startTime = Date.now();
    const steps: SimulationStep[] = [];
    const logs: string[] = [];

    logs.push('[Chat Verification Engine] Initializing rigorous chat security and state integrity suite...');

    const now = Date.now();

    // Setup Test Fixtures: Roles
    const customerUser: AuthUser = {
      id: `u_cust_chat_${now}`,
      email: `chat.client.${now}@example.com`,
      name: 'Elena Rostova',
      phone: '+351 919 555 111',
      role: 'customer',
      specialistStatus: null,
      password: 'PassSecure123!'
    };

    const tpOperatorUser: AuthUser = {
      id: `u_tp_chat_${now}`,
      email: `chat.tp.${now}@nordbase.pt`,
      name: 'João TP Portimão',
      phone: '+351 920 888 222',
      role: 'operator',
      specialistStatus: 'approved',
      dashboardNumber: 'PT-OP-[Chat-Test]',
      password: 'PassSecure123!'
    };

    const unlockedSpecialistUser: AuthUser = {
      id: `u_spec_unlocked_${now}`,
      email: `spec.unlocked.${now}@contractor.pt`,
      name: 'Vasco Contractor',
      phone: '+351 931 777 333',
      role: 'specialist',
      specialistStatus: 'approved',
      password: 'PassSecure123!'
    };

    const unassignedSpecialistUser: AuthUser = {
      id: `u_spec_unassigned_${now}`,
      email: `spec.unassigned.${now}@contractor.pt`,
      name: 'Other Contractor (No Access)',
      phone: '+351 931 999 444',
      role: 'specialist',
      specialistStatus: 'approved',
      password: 'PassSecure123!'
    };

    const superAdminUser: AuthUser = {
      id: `u_admin_chat_${now}`,
      email: `admin.chat.${now}@nordbase.pt`,
      name: 'SuperAdmin Auditor',
      role: 'super_admin',
      specialistStatus: 'approved',
      password: 'PassSecure123!'
    };

    // ------------------------------------------------------------------
    // TEST 1: Channel Permission Matrix & Isolation Guard
    // ------------------------------------------------------------------
    const step1Logs: string[] = [];
    step1Logs.push('[Chat Matrix] Testing permissions across 4 distinct communication channels...');

    // Mock active unlocked job
    const mockActiveJob: Job = {
      id: `job_chat_test_${now}`,
      customerName: customerUser.name,
      customerPhone: customerUser.phone,
      specificLocation: 'Rua do Comercio 15, Portimão',
      description: 'Leak in main bathroom valve',
      status: 'active',
      city: 'Portimão',
      category: 'Repairs' as ServiceCategory,
      operatorId: tpOperatorUser.id,
      unlockedBySpecialistId: unlockedSpecialistUser.id,
      offeredSpecialistIds: [unlockedSpecialistUser.id],
      estimatedHours: 2,
      estimatedValue: 120,
      leadPrice: 15,
      createdAt: new Date().toISOString(),
      messages: [],
      timeline: []
    };

    // Assertions for Test 1
    // 1. Customer CAN write to customer_operator
    const custToOpAllowed = canSendMessage('customer', 'operator', { scope: 'job', jobStatus: 'active', channel: 'customer_operator' });
    // 2. Customer CANNOT write to operator_specialist
    const custToOpSpecAllowed = canSendMessage('customer', 'operator', { scope: 'job', jobStatus: 'active', channel: 'operator_specialist' });
    // 3. Unassigned Specialist CANNOT view job chat
    const unassignedViewAllowed = canViewChat(unassignedSpecialistUser, { type: 'job', job: mockActiveJob, channel: 'customer_operator' });
    // 4. Unlocked Specialist CAN view operator_specialist
    const unlockedViewOpSpecAllowed = canViewChat(unlockedSpecialistUser, { type: 'job', job: mockActiveJob, channel: 'operator_specialist' });
    // 5. Unlocked Specialist CAN view customer_specialist when job is active
    const unlockedViewCustSpecAllowed = canViewChat(unlockedSpecialistUser, { type: 'job', job: mockActiveJob, channel: 'customer_specialist' });
    // 6. Pre-unlock job guard: if status is 'pending_operator', direct customer_specialist messaging is BLOCKED
    const pendingJob: Job = { ...mockActiveJob, status: 'pending_operator' };
    const preUnlockDirectChatAllowed = canSendMessage('specialist', 'customer', { scope: 'job', jobStatus: 'pending_operator', channel: 'customer_specialist' });
    const customerPreUnlockViewAllowed = canViewChat(customerUser, { type: 'job', job: pendingJob, channel: 'customer_specialist' });

    step1Logs.push(` - Customer -> Operator channel allowed: ${custToOpAllowed}`);
    step1Logs.push(` - Customer -> Operator-Specialist channel blocked: ${!custToOpSpecAllowed}`);
    step1Logs.push(` - Unassigned Specialist access blocked: ${!unassignedViewAllowed}`);
    step1Logs.push(` - Unlocked Specialist Operator channel access: ${unlockedViewOpSpecAllowed}`);
    step1Logs.push(` - Pre-unlock Direct Chat Guard blocked: ${!preUnlockDirectChatAllowed}`);

    const matrixPassed = custToOpAllowed &&
      !custToOpSpecAllowed &&
      !unassignedViewAllowed &&
      unlockedViewOpSpecAllowed &&
      unlockedViewCustSpecAllowed &&
      !preUnlockDirectChatAllowed &&
      !customerPreUnlockViewAllowed;

    steps.push({
      id: 'chat_step1_matrix',
      name: 'Security Test: Multi-Channel Permission & Isolation Matrix',
      description: 'Validates strict cross-role message boundary rules, channel isolation, and pre-unlock guards',
      agentRole: 'agent_1_super_admin',
      status: matrixPassed ? 'passed' : 'failed',
      durationMs: 30,
      logs: step1Logs,
      assertions: [
        { label: 'Customer can message Operator in customer_operator channel', passed: custToOpAllowed },
        { label: 'Customer blocked from internal operator_specialist channel', passed: !custToOpSpecAllowed },
        { label: 'Unassigned Specialist blocked from viewing lead chat', passed: !unassignedViewAllowed },
        { label: 'Unlocked Specialist granted access to operator_specialist & customer_specialist', passed: unlockedViewOpSpecAllowed && unlockedViewCustSpecAllowed },
        { label: 'Pre-unlock direct Customer-Specialist chat strictly blocked', passed: !preUnlockDirectChatAllowed && !customerPreUnlockViewAllowed }
      ]
    });

    // ------------------------------------------------------------------
    // TEST 2: Real-time Multi-Turn Dialogue & Store Synchronization
    // ------------------------------------------------------------------
    const step2Logs: string[] = [];
    step2Logs.push('[Dialogue Verification] Executing full 4-turn multi-user dialogue in live store...');

    // 1. Create actual job in store
    const realJob = await store.createJobRequest(customerUser.name, customerUser.phone, 'Rua da Marina 88, Portimão', 'Urgent plumber request for burst pipe');
    const jobId = realJob.id;
    await store.claimJob(jobId, tpOperatorUser.id);

    // Turn 1: Customer messages TP
    await store.addMessage(jobId, 'customer', customerUser.name, 'Hello! Water is leaking fast under the sink, can you send someone immediately?', 'customer_operator');
    step2Logs.push(`Turn 1 [Customer -> TP]: Message posted to 'customer_operator'`);

    // Turn 2: TP replies to Customer
    await store.addMessage(jobId, 'operator', tpOperatorUser.name, 'Hello Elena! I am dispatching our top Portimão plumber right now.', 'customer_operator');
    step2Logs.push(`Turn 2 [TP -> Customer]: Message posted to 'customer_operator'`);

    // Turn 3: TP messages Specialist in internal channel
    await store.addMessage(jobId, 'operator', tpOperatorUser.name, 'Vasco, please confirm if you have copper pipe fittings for Job #' + jobId, 'operator_specialist');
    step2Logs.push(`Turn 3 [TP -> Specialist]: Message posted to internal 'operator_specialist'`);

    // Turn 4: Specialist unlocks lead and messages Customer directly in customer_specialist
    const spec: Specialist = {
      id: unlockedSpecialistUser.id,
      name: unlockedSpecialistUser.name,
      phone: unlockedSpecialistUser.phone,
      category: 'Repairs' as ServiceCategory,
      categories: ['Repairs'],
      city: 'Portimão',
      balance: 100,
      unlockedJobs: [],
      status: 'approved',
      skillsDescription: 'Master Plumber'
    };
    store.updateSpecialists([...store.getState().specialists, spec]);
    await store.topupSpecialist(spec.id, 50);
    await store.offerJobToSpecialists(jobId, 2, 100, 15, 'Burst Pipe Repair', [spec.id]);
    await store.expressInterest(jobId, spec.id);
    await store.selectSpecialistForJob(jobId, spec.id);
    await store.unlockJob(jobId, spec.id);

    await store.addMessage(jobId, 'specialist', spec.name, 'Hello Elena! I have unlocked your request. Arriving in 15 minutes with copper fittings.', 'customer_specialist');
    step2Logs.push(`Turn 4 [Specialist -> Customer]: Direct message posted in 'customer_specialist'`);

    // Fetch updated job from store and audit messages
    const updatedJobState = store.getState().jobs.find(j => j.id === jobId);
    const msgs = updatedJobState?.messages || [];
    step2Logs.push(`Store Verification: Total recorded messages for Job #${jobId}: ${msgs.length}`);

    const hasCustOpMsg = msgs.some(m => m.channel === 'customer_operator' && m.sender === 'customer');
    const hasOpCustMsg = msgs.some(m => m.channel === 'customer_operator' && m.sender === 'operator');
    const hasOpSpecMsg = msgs.some(m => m.channel === 'operator_specialist');
    const hasSpecCustMsg = msgs.some(m => m.channel === 'customer_specialist' && m.sender === 'specialist');

    const dialoguePassed = msgs.length >= 4 && hasCustOpMsg && hasOpCustMsg && hasOpSpecMsg && hasSpecCustMsg;

    steps.push({
      id: 'chat_step2_dialogue',
      name: 'E2E Test: Multi-Turn Conversation & Store Delivery Integrity',
      description: 'Verifies real-time message persistence, sequence ordering, and channel distribution across 4 dialogue turns',
      agentRole: 'agent_3_tp',
      status: dialoguePassed ? 'passed' : 'failed',
      durationMs: 45,
      logs: step2Logs,
      assertions: [
        { label: 'Store recorded all 4 conversation turns', passed: msgs.length >= 4 },
        { label: 'Customer <-> Operator messages verified', passed: hasCustOpMsg && hasOpCustMsg },
        { label: 'Internal Operator <-> Specialist channel messages verified', passed: hasOpSpecMsg },
        { label: 'Direct Specialist <-> Customer channel messages verified', passed: hasSpecCustMsg }
      ]
    });

    // ------------------------------------------------------------------
    // TEST 3: Attachment Security & Photo Verification
    // ------------------------------------------------------------------
    const step3Logs: string[] = [];
    step3Logs.push('[Attachment Guard] Testing image/document upload permissions in job chat...');

    await store.addMessage(
      jobId,
      'customer',
      customerUser.name,
      'Here is the photo of the leaking valve under the sink.',
      'customer_operator',
      'https://images.unsplash.com/photo-1585704032915-c3400ca199e7?w=800',
      'pipe_leak_photo.jpg'
    );

    const jobWithAttachment = store.getState().jobs.find(j => j.id === jobId)!;
    const attachmentMsg = jobWithAttachment.messages.find(m => m.attachmentUrl);

    step3Logs.push(`Attachment recorded in chat: ${attachmentMsg?.attachmentName || 'None'}`);

    const customerCanViewAtt = canViewAttachment(customerUser, { url: attachmentMsg?.attachmentUrl || '', channel: 'customer_operator' }, jobWithAttachment);
    const operatorCanViewAtt = canViewAttachment(tpOperatorUser, { url: attachmentMsg?.attachmentUrl || '', channel: 'customer_operator' }, jobWithAttachment);
    const unassignedCanViewAtt = canViewAttachment(unassignedSpecialistUser, { url: attachmentMsg?.attachmentUrl || '', channel: 'customer_operator' }, jobWithAttachment);

    step3Logs.push(` - Customer attachment view access: ${customerCanViewAtt}`);
    step3Logs.push(` - Operator attachment view access: ${operatorCanViewAtt}`);
    step3Logs.push(` - Unassigned Specialist attachment view access: ${!unassignedCanViewAtt}`);

    const attachmentPassed = !!attachmentMsg && customerCanViewAtt && operatorCanViewAtt && !unassignedCanViewAtt;

    steps.push({
      id: 'chat_step3_attachment',
      name: 'Security Test: Attachment Privacy & Scope Authorization',
      description: 'Ensures uploaded photos & diagnostic docs inherit strict channel visibility rules',
      agentRole: 'agent_5_customer',
      status: attachmentPassed ? 'passed' : 'failed',
      durationMs: 30,
      logs: step3Logs,
      assertions: [
        { label: 'Attachment stored cleanly with URL and filename', passed: !!attachmentMsg },
        { label: 'Customer & TP can view attachment', passed: customerCanViewAtt && operatorCanViewAtt },
        { label: 'Unassigned Specialist blocked from viewing client photo', passed: !unassignedCanViewAtt }
      ]
    });

    // ------------------------------------------------------------------
    // TEST 4: Operator Dispute Arbitration & Intervention Messages
    // ------------------------------------------------------------------
    const step4Logs: string[] = [];
    step4Logs.push('[Dispute Intervention] Testing TP operator arbitration message injection...');

    await store.arbitrateJobDispute(
      jobId,
      'TP Operator João is now arbitrating this request. Both parties please summarize agreed work scope.'
    );

    const auditedJob = store.getState().jobs.find(j => j.id === jobId)!;
    const disputeMsg = auditedJob.messages.find(m => m.content.includes('arbitrating this request') || m.content.includes('DISPUTE'));

    step4Logs.push(`Dispute intervention message inserted: ${disputeMsg ? 'YES' : 'NO'}`);
    if (disputeMsg) {
      step4Logs.push(` - Sender: ${disputeMsg.senderName} (${disputeMsg.sender})`);
      step4Logs.push(` - Content: ${disputeMsg.content}`);
    }

    const disputePassed = !!disputeMsg && disputeMsg.sender === 'operator';

    steps.push({
      id: 'chat_step4_dispute',
      name: 'Audit Test: Operator Dispute Arbitration Injection',
      description: 'Verifies operator ability to insert authoritative binding instructions into active chats',
      agentRole: 'agent_3_tp',
      status: disputePassed ? 'passed' : 'failed',
      durationMs: 35,
      logs: step4Logs,
      assertions: [
        { label: 'Dispute arbitration message inserted into job chat log', passed: disputePassed }
      ]
    });

    return {
