export class FaultInjectionAgent {
  public static agentTitle = 'Fault Injection & Security Resilience Suite';

  public static async runAllScenarios(): Promise<TestScenario[]> {
    const s1 = await FaultInjectionAgent.runScenarioWalletOverdraftProtection();
    const s2 = await FaultInjectionAgent.runScenarioDoubleLeadPurchaseConflict();
    const s3 = await FaultInjectionAgent.runScenarioInvalidOrderDataHandling();
    return [s1, s2, s3];
  }

  /**
   * Scenario 1: Verify system prevents unlocking leads when specialist has insufficient wallet funds
   */
  public static async runScenarioWalletOverdraftProtection(): Promise<TestScenario> {
    const startTime = Date.now();
    const steps: SimulationStep[] = [];
    const logs: string[] = [];

    logs.push('[Fault Suite] Testing Wallet Overdraft Protection (Insufficient Balance scenario)...');

    // Create a specialist with low balance
    const poorSpec: Specialist = {
      id: `spec_poor_${Date.now()}`,
      name: 'Broke Contractor Test',
      phone: '+351 900 000 001',
      category: 'Home Services',
      categories: ['Home Services'],
      city: 'Portimão',
      balance: 5, // Only €5
      unlockedJobs: [],
      status: 'approved'
    };

    const state = store.getState();
    store.updateSpecialists([...state.specialists, poorSpec]);

    // Create a job with lead price €30
    const job = await store.createJobRequest('Test Overdraft Customer', '+351 911 000 999', 'Portimão Center', 'Electric fault');
    await store.offerJobToSpecialists(job.id, 4, 250, 30, 'High value job', [poorSpec.id]);
    await store.selectSpecialistForJob(job.id, poorSpec.id);

    logs.push(`[Fault Suite] Specialist balance: €${poorSpec.balance}. Attempting to unlock lead costing €${job.leadPrice}...`);

    // Attempt unlock
    const unlockSuccess = await store.unlockJob(job.id, poorSpec.id);

    logs.push(`[Fault Suite] Unlock attempt result: ${unlockSuccess ? 'ALLOWED (FAIL!)' : 'BLOCKED (PASS!)'}`);

    const updatedSpec = store.getState().specialists.find(s => s.id === poorSpec.id);
    const updatedJob = store.getState().jobs.find(j => j.id === job.id);

    const isProtectionWorking = !unlockSuccess && (updatedSpec?.balance === 5) && (updatedJob?.status !== 'active');

    steps.push({
      id: 'fault_s1_step1',
      name: 'Verify Overdraft Lock (Insufficient Funds)',
      description: 'System must reject lead unlock attempt if specialist wallet balance is below lead fee',
      agentRole: 'agent_4_specialist',
      status: isProtectionWorking ? 'passed' : 'failed',
      durationMs: 35,
      logs,
      error: isProtectionWorking ? undefined : 'System allowed lead unlock despite insufficient balance!',
      assertions: [
        { label: 'Unlock transaction returned false', passed: !unlockSuccess },
        { label: 'Wallet balance remained unchanged (€5)', passed: updatedSpec?.balance === 5, details: `€${updatedSpec?.balance}` },
        { label: 'Job contact info remained locked', passed: updatedJob?.status !== 'active' }
      ]
    });

    return {
      id: 'scenario_fault_overdraft',
      title: '🛡️ Fault Test 1: Wallet Overdraft Protection & Fund Guard',
      agentName: 'Fault Injection Agent',
      agentRole: 'agent_4_specialist',
      description: 'Tests resilience against overdraft attempts when purchasing leads with low wallet balance',
      steps,
      status: steps.every(s => s.status === 'passed') ? 'passed' : 'failed',
      startedAt: new Date(startTime).toISOString(),
      completedAt: new Date().toISOString(),
      totalDurationMs: Date.now() - startTime
    };
  }

  /**
   * Scenario 2: Verify double purchase conflict handling
   */
  public static async runScenarioDoubleLeadPurchaseConflict(): Promise<TestScenario> {
    const startTime = Date.now();
    const steps: SimulationStep[] = [];
    const logs: string[] = [];

    logs.push('[Fault Suite] Testing Concurrent Lead Unlock Protection...');

    const specA: Specialist = {
      id: `spec_a_${Date.now()}`,
      name: 'Contractor A',
      phone: '+351 900 111 222',
      category: 'Home Services',
      categories: ['Home Services'],
      city: 'Portimão',
      balance: 100,
      unlockedJobs: [],
      status: 'approved'
    };
    const specB: Specialist = {
      id: `spec_b_${Date.now()}`,
      name: 'Contractor B',
      phone: '+351 900 111 333',
      category: 'Home Services',
      categories: ['Home Services'],
      city: 'Portimão',
      balance: 100,
      unlockedJobs: [],
      status: 'approved'
    };

    store.updateSpecialists([...store.getState().specialists, specA, specB]);

    const job = await store.createJobRequest('Conflict Customer', '+351 911 222 333', 'Portimão', 'Plumbing issue');
    await store.offerJobToSpecialists(job.id, 2, 100, 15, 'Plumbing job', [specA.id, specB.id]);
    await store.selectSpecialistForJob(job.id, specA.id);

    // Spec A unlocks
    const resA = await store.unlockJob(job.id, specA.id);
    logs.push(`[Fault Suite] Spec A unlock result: ${resA}`);

    // Spec B tries to unlock the exact same job
    const resB = await store.unlockJob(job.id, specB.id);
    logs.push(`[Fault Suite] Spec B duplicate unlock result: ${resB}`);

    const specBAfter = store.getState().specialists.find(s => s.id === specB.id);

    const pass = resA === true && resB === false && specBAfter?.balance === 100;

    steps.push({
      id: 'fault_s2_step1',
      name: 'Prevent Duplicate Lead Deductions',
      description: 'Ensure second contractor cannot unlock or be charged for an already assigned active lead',
      agentRole: 'agent_4_specialist',
      status: pass ? 'passed' : 'failed',
      durationMs: 40,
      logs,
      assertions: [
        { label: 'First contractor unlocked successfully', passed: resA },
        { label: 'Second contractor unlock blocked', passed: !resB },
        { label: 'Second contractor balance untouched (€100)', passed: specBAfter?.balance === 100 }
      ]
    });

    return {
      id: 'scenario_fault_double_unlock',
      title: '🛡️ Fault Test 2: Double Lead Unlock & Balance Deduct Guard',
      agentName: 'Fault Injection Agent',
      agentRole: 'agent_4_specialist',
      description: 'Verifies system prevents duplicate lead fee deductions and double assignment conflicts',
      steps,
      status: steps.every(s => s.status === 'passed') ? 'passed' : 'failed',
      startedAt: new Date(startTime).toISOString(),
      completedAt: new Date().toISOString(),
      totalDurationMs: Date.now() - startTime
    };
  }

  /**
   * Scenario 3: Validate graceful handling of invalid or empty order requests
   */
  public static async runScenarioInvalidOrderDataHandling(): Promise<TestScenario> {
    const startTime = Date.now();
    const steps: SimulationStep[] = [];
    const logs: string[] = [];

    logs.push('[Fault Suite] Testing Order Request Validation and Data Sanitization...');

    // Attempt creating order with fallback parameters
    const job = await store.createJobRequest(
      'Anon Customer',
