    const testSampleText = "NordBase Territorial Partner in Portimão issued a Recibo Verde for Quadro Elétrico repair under SLA.";

    // Simulate checking terms against glossary dictionary
    const recognizedTerms = baselineApprovedGlossary.filter(g => testSampleText.toLowerCase().includes(g.term.toLowerCase()));

    step2Logs.push(`Input Text: "${testSampleText}"`);
    step2Logs.push(`Recognized Protected Glossary Terms: ${recognizedTerms.map(t => t.term).join(', ')}`);

