    store.getState().selectedCategory = 'Repairs';
    const matchedFaroOp = store.findMatchingOperatorForCity('Faro');
    const jobFaro = await store.createJobRequest(
      'João Ferreira',
      '+351 914 999 000',
      'Montenegro, Faro',
      'Main panel circuit breaker trip emergency',
      [],
      matchedFaroOp?.id
    );
