    store.getState().selectedCity = prevCity;
    store.getState().selectedCategory = prevCat;

    const ptmMatchOk = !!jobPtm.operatorId && jobPtm.operatorId === matchedPtmOp?.id;
    const lagosMatchOk = !!jobLagos.operatorId && jobLagos.operatorId === matchedLagosOp?.id;
    const faroMatchOk = !!jobFaro.operatorId && jobFaro.operatorId === matchedFaroOp?.id;

    steps.push({
      id: 'geo_step2',
      name: 'Automatic City-Based Geo Lead Routing',
      description: 'Validates instant routing of incoming leads in Portimão, Lagos, and Faro to respective TPs.',
      agentRole: 'agent_3_tp',
      status: (ptmMatchOk && lagosMatchOk && faroMatchOk) ? 'passed' : 'failed',
