    const failoverRes = await store.triggerSLAFailover(jobFaro.id, 15);

    const updatedJob = store.getState().jobs.find(j => j.id === jobFaro.id);
    const rpEscalatedOk = updatedJob?.operatorId === failoverRes.failoverTarget?.id;

    const timelineHasFailover = updatedJob?.timeline?.some(t => t.action.includes('SLA Failover')) || false;
    const messageHasFailover = updatedJob?.messages.some(m => m.content.includes('PODSTRAHOVKA')) || false;
    const auditHasFailover = store.getState().auditLogs.some(a => a.action === 'SLA Failover Executed') || false;

    step3Logs.push(`Failover Result: ${failoverRes.success ? 'SUCCESS' : 'FAILED'}`);
    step3Logs.push(`New Operator ID: ${updatedJob?.operatorId} (${failoverRes.failoverTarget?.name})`);

    const failoverPassed = rpEscalatedOk && timelineHasFailover && messageHasFailover && auditHasFailover;

    steps.push({
      id: 'geo_step3',
      name: 'Backup SLA Failover ("Podstrahovka") Escalate to RP / SuperAdmin',
