        { label: 'System chat alert "PODSTRAHOVKA" posted to customer thread', passed: messageHasFailover },
        { label: 'Enterprise Audit Log entry generated for SLA Failover', passed: auditHasFailover }
      ]
    });

    const scenarioPassed = steps.every(s => s.status === 'passed');

    return {
      id: 'sc_territory_routing_failover',
      title: 'Territory Geo-Zoning & Podstrahovka SLA Failover Suite',
      agentName: 'Agent 3 & 2 (Geo-Routing & SLA Guard)',
