      const superAdminUser = this.state.users.find(u => u.role === 'super_admin') || {
        id: 'u_super_admin_01',
        email: 'olegadmin',
        name: 'Director NordBase /01',
        phone: '+351 900 000 001',
        role: 'super_admin',
        region: 'All',
        dashboardNumber: '01',
        isNewUser: false,
